module.exports = {
  root: true,
  env: { browser: true, es2020: true },
  extends: [
    'eslint:recommended',
    'plugin:@typescript-eslint/recommended',
    'plugin:react-hooks/recommended',
  ],
  ignorePatterns: ['dist', '.eslintrc.cjs'],
  parser: '@typescript-eslint/parser',
  plugins: ['react-refresh'],
  rules: {
    '@typescript-eslint/no-explicit-any': 'warn',
    'react-hooks/exhaustive-deps': 'warn'
  },
}

import { Router, Request, Response, NextFunction } from 'express';
import jwt from 'jsonwebtoken';
import { auraDb } from './db';

const router = Router();
const JWT_SECRET = process.env.JWT_SECRET || 'aura_secure_jwt_secret_dev_key_2026';

// Helper for JWT extraction
export function authenticateToken(req: Request, res: Response, next: NextFunction) {
  const authHeader = req.headers['authorization'];
  if (!authHeader) {
    return next();
  }
  const token = authHeader.split(' ')[1];
  if (!token) {
    return next();
  }
  jwt.verify(token, JWT_SECRET, (err: any, user: any) => {
    if (err) {
      return res.status(401).json({ detail: 'Could not validate credentials: invalid token' });
    }
    (req as any).user = user;
    next();
  });
}

// 1. Health
router.get('/health', (_req: Request, res: Response) => {
  res.json({
    status: 'healthy',
    service: 'AURA Dynamic Mental Health & Distress API',
    timestamp: new Date().toISOString(),
    version: '1.0.0'
  });
});

// 2. Auth Routes
router.post('/auth/login', (req: Request, res: Response) => {
  const { email, role = 'participant', name } = req.body || {};
  if (!email) {
    return res.status(400).json({ detail: 'Email is required' });
  }

  const db = auraDb.db;
  let user = db.users.find((u) => u.email.toLowerCase() === email.toLowerCase());

  if (!user) {
    const isWorker = email.includes('worker') || email.includes('admin') || role === 'support_worker';
    user = {
      id: `usr-${Date.now()}`,
      email,
      role: isWorker ? 'support_worker' : 'participant',
      name: name || (isWorker ? 'Support Specialist' : 'Participant User'),
      consent_given: true,
      created_at: new Date().toISOString()
    };
    db.users.push(user);
    auraDb.save();
  }

  const token = jwt.sign(
    { sub: user.id, email: user.email, role: user.role, name: user.name },
    JWT_SECRET,
    { expiresIn: '24h' }
  );

  res.json({
    access_token: token,
    token_type: 'bearer',
    user
  });
});

router.get('/auth/me', (req: Request, res: Response) => {
  const authHeader = req.headers['authorization'];
  if (!authHeader) {
    return res.status(401).json({ detail: 'Not authenticated' });
  }
  const token = authHeader.split(' ')[1];
  try {
    const decoded: any = jwt.verify(token, JWT_SECRET);
    const user = auraDb.db.users.find((u) => u.id === decoded.sub || u.email === decoded.email);
    if (!user) {
      return res.status(404).json({ detail: 'User not found' });
    }
    res.json(user);
  } catch (err) {
    res.status(401).json({ detail: 'Could not validate credentials' });
  }
});

router.post('/auth/logout', (_req: Request, res: Response) => {
  res.json({ message: 'Successfully logged out' });
});

// 3. Participants
router.get('/participants', (_req: Request, res: Response) => {
  const db = auraDb.db;
  const result = db.participants.map((p) => {
    const notes = db.support_notes.filter((n) => n.participant_id === p.id);
    const checkIns = db.check_ins.filter((c) => c.participant_id === p.id);
    return {
      ...p,
      notes,
      check_ins: checkIns
    };
  });
  res.json(result);
});

router.get('/participants/:id', (req: Request, res: Response) => {
  const pId = req.params.id;
  const db = auraDb.db;
  const participant = db.participants.find((p) => p.id === pId);
  if (!participant) {
    return res.status(404).json({ detail: 'Participant not found' });
  }
  const notes = db.support_notes.filter((n) => n.participant_id === pId);
  const checkIns = db.check_ins.filter((c) => c.participant_id === pId);
  const consent = db.consents.find((c) => c.participant_id === pId);
  res.json({
    ...participant,
    notes,
    check_ins: checkIns,
    consent
  });
});

router.post('/participants', (req: Request, res: Response) => {
  const body = req.body || {};
  const db = auraDb.db;
  const id = body.id || `P-${Math.floor(1000 + Math.random() * 9000)}`;

  const newParticipant = {
    id,
    user_id: body.userId,
    consent_given: body.consentGiven ?? true,
    status: body.status || 'Stable',
    preferred_support: body.preferredSupport || 'Human support worker',
    language: body.language || 'English',
    age_group: body.ageGroup || '25-34',
    assigned_worker: body.assignedWorker,
    region: body.region || 'Global',
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString()
  };

  db.participants.push(newParticipant);

  // Initialize consent record
  db.consents.push({
    id: `cst-${Date.now()}`,
    participant_id: id,
    wellbeing_check_ins: true,
    support_worker_sharing: true,
    optional_free_text_sharing: true,
    optional_voice_feature: true,
    community_aggregate_analytics: false,
    status: 'active',
    version: '1.0',
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString()
  });

  auraDb.save();
  res.status(201).json(newParticipant);
});

router.patch('/participants/:id', (req: Request, res: Response) => {
  const pId = req.params.id;
  const db = auraDb.db;
  const index = db.participants.findIndex((p) => p.id === pId);
  if (index === -1) {
    return res.status(404).json({ detail: 'Participant not found' });
  }

  const p = db.participants[index];
  const body = req.body || {};

  if (body.status !== undefined) p.status = body.status;
  if (body.assignedWorker !== undefined) p.assigned_worker = body.assignedWorker;
  if (body.preferredSupport !== undefined) p.preferred_support = body.preferredSupport;
  if (body.language !== undefined) p.language = body.language;
  if (body.lastReviewDate !== undefined) p.last_review_date = body.lastReviewDate;
  p.updated_at = new Date().toISOString();

  auraDb.save();
  res.json(p);
});

router.post('/participants/:id/notes', (req: Request, res: Response) => {
  const pId = req.params.id;
  const { author, text, actionTaken } = req.body || {};
  if (!text) {
    return res.status(400).json({ detail: 'Note text is required' });
  }
  const db = auraDb.db;
  const note = {
    id: `sn-${Date.now()}`,
    participant_id: pId,
    author: author || 'Support Worker',
    timestamp: new Date().toISOString(),
    text,
    action_taken: actionTaken
  };
  db.support_notes.push(note);
  auraDb.save();
  res.status(201).json(note);
});

router.post('/participants/:id/review', (req: Request, res: Response) => {
  const pId = req.params.id;
  const db = auraDb.db;
  const participant = db.participants.find((p) => p.id === pId);
  if (participant) {
    participant.last_review_date = new Date().toISOString();
    participant.updated_at = new Date().toISOString();
    auraDb.save();
  }
  res.json({ message: 'Marked reviewed', lastReviewDate: participant?.last_review_date });
});

// 4. Check-ins
router.get('/check-ins', (req: Request, res: Response) => {
  const { participant_id } = req.query;
  const db = auraDb.db;
  if (participant_id) {
    return res.json(db.check_ins.filter((c) => c.participant_id === participant_id));
  }
  res.json(db.check_ins);
});

router.post('/check-ins', (req: Request, res: Response) => {
  const body = req.body || {};
  const { participantId, wellbeing, stress, sleep, safety, connection } = body;
  if (!participantId || wellbeing === undefined || stress === undefined) {
    return res.status(400).json({ detail: 'Participant ID and wellbeing scores are required' });
  }

  const db = auraDb.db;
  // Check consent
  const consent = db.consents.find((c) => c.participant_id === participantId);
  if (consent && (!consent.wellbeing_check_ins || consent.status === 'revoked')) {
    return res.status(403).json({ detail: 'Participant has not consented to wellbeing check-ins.' });
  }

  const checkIn = {
    id: `chk-${Date.now()}`,
    participant_id: participantId,
    wellbeing: Number(wellbeing),
    stress: Number(stress),
    sleep: Number(sleep || 3),
    safety: String(safety || 'Yes'),
    connection: Number(connection || 3),
    support_requested: Boolean(body.supportRequested),
    immediate_safety_concern: Boolean(body.immediateSafetyConcern),
    calculated_score: body.calculatedScore,
    notes: body.notes || body.optionalNote,
    optional_note: body.optionalNote,
    share_note_with_worker: body.shareNoteWithWorker ?? true,
    voice_input_used: body.voiceInputUsed ?? false,
    timestamp: new Date().toISOString(),
    created_at: new Date().toISOString()
  };

  db.check_ins.unshift(checkIn);

  // Record risk history
  if (checkIn.calculated_score !== undefined) {
    db.risk_history.push({
      id: `rh-${Date.now()}`,
      participant_id: participantId,
      score: checkIn.calculated_score,
      level: checkIn.calculated_score >= 75 ? 'CRITICAL' : checkIn.calculated_score >= 60 ? 'HIGH' : checkIn.calculated_score >= 40 ? 'MODERATE' : 'LOW',
      source: 'check_in',
      recorded_at: new Date().toISOString()
    });
  }

  auraDb.save();
  res.status(201).json(checkIn);
});

// 5. Reflections
router.get('/reflections', (req: Request, res: Response) => {
  const { participant_id } = req.query;
  const db = auraDb.db;
  if (participant_id) {
    return res.json(db.reflections.filter((r) => r.participant_id === participant_id));
  }
  res.json(db.reflections);
});

router.post('/reflections', (req: Request, res: Response) => {
  const body = req.body || {};
  const db = auraDb.db;
  const reflection = {
    id: `ref-${Date.now()}`,
    participant_id: body.participantId,
    type: body.type || 'text',
    transcript: body.transcript || '',
    audio_recorded: Boolean(body.audioRecorded),
    share_with_worker: body.shareWithWorker ?? true,
    sentiment: body.sentiment,
    language_signal: body.languageSignal,
    has_urgent_safety_mention: Boolean(body.hasUrgentSafetyMention),
    submitted_at: new Date().toISOString()
  };
  db.reflections.unshift(reflection);
  auraDb.save();
  res.status(201).json(reflection);
});

// 6. Risk Predictions & History
router.post('/risk/predictions', (req: Request, res: Response) => {
  const body = req.body || {};
  const db = auraDb.db;
  const prediction = {
    id: `pred-${Date.now()}`,
    participant_id: body.participantId,
    distress_score: body.distressScore || 50,
    risk_level: body.riskLevel || 'MODERATE',
    trajectory: body.trajectory || 'Stable',
    confidence: body.confidence || 0.88,
    change_delta: body.changeDelta,
    contributing_factors: body.contributingFactors,
    factor_breakdown: body.factorBreakdown,
    explanation: body.explanation,
    requires_human_review: Boolean(body.requiresHumanReview),
    is_explicit_safety_concern: Boolean(body.isExplicitSafetyConcern),
    created_at: new Date().toISOString()
  };
  db.risk_predictions.unshift(prediction);
  auraDb.save();
  res.status(201).json(prediction);
});

router.get('/risk/predictions', (req: Request, res: Response) => {
  const { participant_id } = req.query;
  const db = auraDb.db;
  if (participant_id) {
    return res.json(db.risk_predictions.filter((p) => p.participant_id === participant_id));
  }
  res.json(db.risk_predictions);
});

router.get('/risk/history/:id', (req: Request, res: Response) => {
  const pId = req.params.id;
  const db = auraDb.db;
  const hist = db.risk_history.filter((h) => h.participant_id === pId);
  res.json(hist);
});

// 7. Alerts
router.get('/alerts', (req: Request, res: Response) => {
  const { participant_id, status } = req.query;
  const db = auraDb.db;
  let list = db.alerts;
  if (participant_id) {
    list = list.filter((a) => a.participant_id === participant_id);
  }
  if (status) {
    list = list.filter((a) => a.status === status);
  }
  res.json(list);
});

router.post('/alerts', (req: Request, res: Response) => {
  const body = req.body || {};
  const db = auraDb.db;
  const alert = {
    id: `ALT-${Date.now()}`,
    participant_id: body.participantId,
    category: body.category || 'ELEVATED_DISTRESS',
    severity: body.severity || 'ORANGE',
    title: body.title || 'Distress Alert',
    reason: body.reason || 'Noticeable change in check-in signals',
    description: body.description,
    recommended_action: body.recommendedAction,
    status: body.status || 'NEW',
    score: body.score || 65,
    change_delta: body.changeDelta,
    assigned_to: body.assignedTo,
    requires_human_review: body.requiresHumanReview ?? true,
    contributing_factors: body.contributingFactors,
    trajectory: body.trajectory,
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString()
  };
  db.alerts.unshift(alert);
  auraDb.save();
  res.status(201).json(alert);
});

router.patch('/alerts/:id', (req: Request, res: Response) => {
  const aId = req.params.id;
  const db = auraDb.db;
  const alert = db.alerts.find((a) => a.id === aId);
  if (!alert) {
    return res.status(404).json({ detail: 'Alert not found' });
  }
  const body = req.body || {};
  if (body.status) alert.status = body.status;
  if (body.decisionNotes) alert.decision_notes = body.decisionNotes;
  if (body.actionTaken) alert.action_taken = body.actionTaken;
  if (body.reviewedBy) alert.reviewed_by = body.reviewedBy;
  if (body.humanDecision) alert.human_decision = body.humanDecision;
  alert.reviewed_at = new Date().toISOString();
  alert.updated_at = new Date().toISOString();

  auraDb.save();
  res.json(alert);
});

// 8. Notifications
router.get('/notifications', (req: Request, res: Response) => {
  const { unread_only } = req.query;
  const db = auraDb.db;
  if (unread_only === 'true') {
    return res.json(db.notifications.filter((n) => !n.read));
  }
  res.json(db.notifications);
});

router.post('/notifications', (req: Request, res: Response) => {
  const body = req.body || {};
  const db = auraDb.db;
  const notif = {
    id: `notif-${Date.now()}`,
    user_id: body.userId,
    participant_id: body.participantId,
    category: body.category || 'general',
    filter_category: body.filterCategory || 'general',
    severity: body.severity || 'INFO',
    title: body.title,
    message: body.message,
    read: false,
    action_label: body.actionLabel,
    action_view: body.actionView,
    action_participant_id: body.actionParticipantId,
    metadata_json: body.metadata,
    created_at: new Date().toISOString()
  };
  db.notifications.unshift(notif);
  auraDb.save();
  res.status(201).json(notif);
});

router.patch('/notifications/:id/read', (req: Request, res: Response) => {
  const nId = req.params.id;
  const db = auraDb.db;
  const notif = db.notifications.find((n) => n.id === nId);
  if (notif) {
    notif.read = true;
    auraDb.save();
  }
  res.json({ message: 'Marked read' });
});

router.post('/notifications/mark-all-read', (_req: Request, res: Response) => {
  const db = auraDb.db;
  let count = 0;
  db.notifications.forEach((n) => {
    if (!n.read) {
      n.read = true;
      count++;
    }
  });
  auraDb.save();
  res.json({ markedRead: count });
});

// 9. Interventions & Follow-ups
router.get('/interventions', (req: Request, res: Response) => {
  const { participant_id } = req.query;
  const db = auraDb.db;
  if (participant_id) {
    return res.json(db.interventions.filter((i) => i.participant_id === participant_id));
  }
  res.json(db.interventions);
});

router.post('/interventions', (req: Request, res: Response) => {
  const body = req.body || {};
  const db = auraDb.db;
  const intv = {
    id: `intv-${Date.now()}`,
    participant_id: body.participantId,
    alert_id: body.alertId,
    intervention_type: body.interventionType,
    assigned_worker: body.assignedWorker || 'Support Specialist',
    date: body.date || new Date().toISOString(),
    outcome: body.outcome || 'in_progress',
    notes: body.notes || '',
    previous_risk: body.previousRisk,
    follow_up_risk: body.followUpRisk,
    created_at: new Date().toISOString()
  };
  db.interventions.unshift(intv);
  auraDb.save();
  res.status(201).json(intv);
});

router.get('/follow-ups', (req: Request, res: Response) => {
  const { participant_id } = req.query;
  const db = auraDb.db;
  if (participant_id) {
    return res.json(db.follow_ups.filter((f) => f.participant_id === participant_id));
  }
  res.json(db.follow_ups);
});

router.post('/follow-ups', (req: Request, res: Response) => {
  const body = req.body || {};
  const db = auraDb.db;
  const followUp = {
    id: `flw-${Date.now()}`,
    participant_id: body.participantId,
    alert_id: body.alertId,
    original_score: body.originalScore || 50,
    intervention_type: body.interventionType || 'Reach-out',
    intervention_date: body.interventionDate || new Date().toISOString(),
    worker_name: body.workerName || 'Support Specialist',
    outcome: body.outcome || 'pending',
    outcome_label: body.outcomeLabel || 'Pending Follow-up',
    notes: body.notes || '',
    created_at: new Date().toISOString()
  };
  db.follow_ups.unshift(followUp);
  auraDb.save();
  res.status(201).json(followUp);
});

// 10. Consents
router.get('/consents/:id', (req: Request, res: Response) => {
  const pId = req.params.id;
  const db = auraDb.db;
  const consent = db.consents.find((c) => c.participant_id === pId);
  if (!consent) {
    return res.json({
      participant_id: pId,
      wellbeing_check_ins: true,
      support_worker_sharing: true,
      optional_free_text_sharing: true,
      optional_voice_feature: true,
      community_aggregate_analytics: false,
      status: 'active',
      version: '1.0'
    });
  }
  res.json(consent);
});

router.patch('/consents/:id', (req: Request, res: Response) => {
  const pId = req.params.id;
  const db = auraDb.db;
  let consent = db.consents.find((c) => c.participant_id === pId);
  const body = req.body || {};
  if (!consent) {
    consent = {
      id: `cst-${Date.now()}`,
      participant_id: pId,
      wellbeing_check_ins: true,
      support_worker_sharing: true,
      optional_free_text_sharing: true,
      optional_voice_feature: true,
      community_aggregate_analytics: false,
      status: 'active',
      version: '1.0',
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString()
    };
    db.consents.push(consent);
  }

  if (body.wellbeing_check_ins !== undefined) consent.wellbeing_check_ins = body.wellbeing_check_ins;
  if (body.support_worker_sharing !== undefined) consent.support_worker_sharing = body.support_worker_sharing;
  if (body.optional_free_text_sharing !== undefined) consent.optional_free_text_sharing = body.optional_free_text_sharing;
  if (body.optional_voice_feature !== undefined) consent.optional_voice_feature = body.optional_voice_feature;
  if (body.community_aggregate_analytics !== undefined) consent.community_aggregate_analytics = body.community_aggregate_analytics;
  if (body.status !== undefined) consent.status = body.status;
  consent.updated_at = new Date().toISOString();

  auraDb.save();
  res.json(consent);
});

router.post('/consents/:id/revoke', (req: Request, res: Response) => {
  const pId = req.params.id;
  const { reason } = req.body || {};
  const db = auraDb.db;
  const consent = db.consents.find((c) => c.participant_id === pId);
  if (consent) {
    consent.status = 'revoked';
    consent.wellbeing_check_ins = false;
    consent.revocation_reason = reason;
    consent.revoked_at = new Date().toISOString();
    consent.updated_at = new Date().toISOString();
    auraDb.save();
  }
  res.json({ message: 'Consent revoked', consent });
});

// 11. Support Resources
router.get('/support-resources', (req: Request, res: Response) => {
  const { region } = req.query;
  const db = auraDb.db;
  if (region) {
    return res.json(db.support_resources.filter((r) => r.region.toLowerCase().includes(String(region).toLowerCase()) || r.region === 'Global'));
  }
  res.json(db.support_resources);
});

// 12. Audit Logs
router.get('/audit-logs', (req: Request, res: Response) => {
  const { category, participant_id, limit = 100 } = req.query;
  const db = auraDb.db;
  let logs = db.audit_logs;
  if (category) {
    logs = logs.filter((l) => l.category === category);
  }
  if (participant_id) {
    logs = logs.filter((l) => l.participant_id === participant_id);
  }
  res.json(logs.slice(0, Number(limit)));
});

router.post('/audit-logs', (req: Request, res: Response) => {
  const body = req.body || {};
  const db = auraDb.db;
  const log = {
    id: `aud-${Date.now()}-${Math.floor(Math.random() * 1000)}`,
    actor_id: body.actorId || 'system',
    actor_role: body.actorRole || 'system',
    actor_name: body.actorName || 'System',
    action: body.action || 'AUDIT_ACTION',
    category: body.category || 'general',
    participant_id: body.participantId,
    target_id: body.targetId,
    description: body.description || '',
    severity: body.severity || 'INFO',
    metadata_json: body.metadata,
    timestamp: new Date().toISOString()
  };
  db.audit_logs.unshift(log);
  auraDb.save();
  res.status(201).json(log);
});

export default router;

import fs from 'fs';
import path from 'path';

export interface UserRecord {
  id: string;
  email: string;
  role: string;
  name: string;
  language?: string;
  age_range?: string;
  support_preference?: string;
  consent_given: boolean;
  created_at: string;
}

export interface ParticipantRecord {
  id: string;
  user_id?: string;
  consent_given: boolean;
  status: string;
  preferred_support: string;
  language: string;
  age_group: string;
  assigned_worker?: string;
  last_review_date?: string;
  region?: string;
  created_at: string;
  updated_at: string;
}

export interface CheckInRecord {
  id: string;
  participant_id: string;
  wellbeing: number;
  stress: number;
  sleep: number;
  safety: string;
  connection: number;
  support_requested: boolean;
  immediate_safety_concern: boolean;
  calculated_score?: number;
  notes?: string;
  optional_note?: string;
  share_note_with_worker: boolean;
  voice_input_used: boolean;
  consent_context?: any;
  timestamp: string;
  created_at: string;
