        <div className="inline-flex items-center space-x-1.5 px-3 py-1.5 rounded-xl bg-[#F9FBFA] border border-[#E7EDEA] text-xs font-bold text-[#5A6B6D]">
          <Sparkles size={14} className="text-[#395B64]" />
          <span>Synthetic Trend Model</span>
        </div>
      </div>

      {/* 4 Stat Metrics Grid */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
        {/* Current Indicator */}
        <div className="p-4 rounded-2xl bg-[#F9FBFA] border border-[#E7EDEA]">
          <span className="text-[11px] font-bold text-[#7F8C8D] uppercase tracking-wider block mb-1">
            Current Indicator
