          <div className="flex items-baseline space-x-2">
            <span className="text-3xl font-black text-[#2C3639]">
              {currentScore}
            </span>
            <span className="text-xs text-[#7F8C8D] font-bold">/ 100</span>
          </div>
          <span className="text-[11px] text-[#5A6B6D] mt-1 block">
