      </div>

      {/* Visual Forecast Chart with Dashed Confidence Range */}
      <div className="p-5 rounded-2xl bg-[#F9FBFA] border border-[#E7EDEA] space-y-3">
        <div className="flex items-center justify-between">
          <h4 className="text-xs font-black uppercase tracking-wider text-[#7F8C8D] flex items-center">
            <Activity size={14} className="mr-1.5 text-[#395B64]" />
            Trajectory Progression & 72h Projection
          </h4>
          <div className="flex items-center space-x-3 text-xs font-semibold">
            <span className="flex items-center text-[#2C3639]">
              <span className="w-3 h-0.5 bg-[#395B64] inline-block mr-1.5"></span>
              Historical
            </span>
            <span className="flex items-center text-[#D68060]">
              <span className="w-3 h-0.5 border-t-2 border-dashed border-[#D68060] inline-block mr-1.5"></span>
              Projected Range
            </span>
          </div>
        </div>

        {/* SVG Visualization */}
        <div className="h-44 w-full relative pt-4 pb-2">
          <svg className="w-full h-full overflow-visible" viewBox="0 0 500 120" preserveAspectRatio="none">
            {/* Grid lines */}
            <line x1="0" y1="20" x2="500" y2="20" stroke="#E7EDEA" strokeWidth="1" />
            <line x1="0" y1="60" x2="500" y2="60" stroke="#E7EDEA" strokeWidth="1" />
            <line x1="0" y1="100" x2="500" y2="100" stroke="#E7EDEA" strokeWidth="1" />

            {/* Threshold line at 70 pts */}
            <line x1="0" y1="36" x2="500" y2="36" stroke="#D68060" strokeDasharray="3,3" strokeWidth="1" opacity="0.5" />

            {/* Render historical line */}
            {(() => {
              const pts = forecast?.historicalSeries || [
                { dayLabel: "Baseline", score: currentScore, isProjected: false },
                { dayLabel: "+24h Projected", score: Math.round((projectedMin + projectedMax) / 2), isProjected: true, min: projectedMin, max: projectedMax }
              ];
              const len = pts.length;
              if (len === 0) return null;

              const step = 460 / Math.max(1, len - 1);
              const getX = (i: number) => 20 + i * step;
              const getY = (score: number) => 110 - (score / 100) * 95;

              // Split into historical and projected
              const histPts = pts.filter(p => !p.isProjected);
              const projPt = pts.find(p => p.isProjected);
              const lastHistIndex = Math.max(0, histPts.length - 1);

              const histPath = histPts.map((p, idx) => `${idx === 0 ? "M" : "L"} ${getX(idx)} ${getY(p.score)}`).join(" ");

              return (
                <>
                  {/* Projected Confidence Band Polygon */}
                  {projPt && projPt.min !== undefined && projPt.max !== undefined && histPts.length > 0 && (
                    <polygon
                      points={`
                        ${getX(lastHistIndex)},${getY(histPts[lastHistIndex].score)} 
                        ${getX(len - 1)},${getY(projPt.max)} 
                        ${getX(len - 1)},${getY(projPt.min)}
                      `}
                      fill="#D68060"
                      fillOpacity="0.15"
                    />
                  )}

                  {/* Historical Solid Line */}
                  {histPts.length > 0 && (
                    <path d={histPath} fill="none" stroke="#395B64" strokeWidth="3" strokeLinecap="round" />
                  )}

                  {/* Projected Dashed Line */}
                  {projPt && histPts.length > 0 && (
                    <line
                      x1={getX(lastHistIndex)}
                      y1={getY(histPts[lastHistIndex].score)}
                      x2={getX(len - 1)}
                      y2={getY(projPt.score)}
                      stroke={isRising ? "#D68060" : "#395B64"}
                      strokeWidth="2.5"
                      strokeDasharray="4,4"
                    />
                  )}

                  {/* Points */}
                  {pts.map((p, idx) => {
                    const cx = getX(idx);
                    const cy = getY(p.score);
                    return (
                      <g key={idx}>
                        <circle
                          cx={cx}
                          cy={cy}
                          r={p.isProjected ? 6 : 5}
                          fill={p.isProjected ? (isRising ? "#D68060" : "#395B64") : "#2C3639"}
                          stroke="#ffffff"
                          strokeWidth="2"
                        />
                        <text
                          x={cx}
                          y={cy - 10}
                          textAnchor="middle"
                          className="text-[10px] font-bold fill-[#2C3639]"
                        >
                          {p.score}
                        </text>
                      </g>
                    );
                  })}
                </>
              );
            })()}
          </svg>
        </div>

        <div className="flex items-center justify-between text-[11px] text-[#7F8C8D] pt-1">
          <span>Past Check-ins (Chronological)</span>
          <span className="font-bold text-[#2C3639]">Next 24–72h Forecast Range</span>
        </div>
      </div>

      {/* Heuristic Disclaimer Box */}
      <div className="p-4 rounded-2xl bg-[#F9FBFA] border border-[#E7EDEA] flex items-start space-x-3 text-xs text-[#5A6B6D]">
        <Info size={16} className="text-[#395B64] shrink-0 mt-0.5" />
        <p className="leading-relaxed">
          <strong>Demonstration Note:</strong> This prototype estimates possible future changes from synthetic historical trends. It is not a clinically validated prediction model. All signals serve solely as prioritized decision-support for human humanitarian workers.
        </p>
      </div>
    </div>
  );
};

import React, { useState } from "react";
import {
  HelpCircle,
  AlertCircle,
  ShieldCheck,
  ChevronDown,
  ChevronUp,
  Info,
  Sparkles,
  UserCheck,
  Scale
} from "lucide-react";
import { FactorContribution, RiskAnalysis, TrajectoryAnalysis } from "../types";

interface Props {
  riskAnalysis?: RiskAnalysis | null;
  trajectory?: TrajectoryAnalysis | null;
  participantId?: string;
  isCompact?: boolean;
  factors?: string[] | FactorContribution[];
  overallConfidence?: string;
  summaryStatement?: string;
}

export const ExplainableAISignal: React.FC<Props> = ({
  riskAnalysis,
  trajectory,
  participantId,
  isCompact = false,
  factors: customFactors,
  overallConfidence = "High (92%)",
  summaryStatement
}) => {
  const [expanded, setExpanded] = useState(!isCompact);

  // Normalize factors list
  let detailedFactorsList: FactorContribution[] = [];

  if (riskAnalysis?.detailedFactors && riskAnalysis.detailedFactors.length > 0) {
    detailedFactorsList = riskAnalysis.detailedFactors;
  } else if (Array.isArray(customFactors) && customFactors.length > 0) {
    if (typeof customFactors[0] === "string") {
      detailedFactorsList = (customFactors as string[]).map((f, i) => ({
        name: f,
        impact: i === 0 ? "high" : i === 1 ? "medium" : "low",
        description: `Identified reflection factor: ${f}`,
        weightPercent: Math.round(100 / customFactors.length)
      }));
    } else {
      detailedFactorsList = customFactors as FactorContribution[];
    }
  } else {
    detailedFactorsList = [
      { name: "Stress Indicators", impact: "high", description: "Perceived situational pressure or emotional load", weightPercent: 32 },
      { name: "Sleep Disruption", impact: "medium", description: "Reported difficulty falling or staying asleep", weightPercent: 24 },
      { name: "Perceived Safety", impact: "medium", description: "Environmental or situational uncertainty", weightPercent: 18 },
      { name: "Social Connection", impact: "low", description: "Reduced contact with friends/family", weightPercent: 14 },
      { name: "Recent Trajectory", impact: "medium", description: "Change across recent check-in reflections", weightPercent: 12 }
    ];
  }

  const score = riskAnalysis?.score ?? trajectory?.currentScore ?? 35;
  const changeVal = riskAnalysis?.change ?? trajectory?.rateOfChange ?? 0;
  const leadSummary = summaryStatement ||
    (riskAnalysis?.factors && riskAnalysis.factors[0]) ||
    trajectory?.summaryDescription ||
    "The distress indicator is based on self-reported stress, sleep quality, and situational safety reflections.";

  const getImpactColor = (impact: string) => {
    switch (impact) {
      case "high":
        return "bg-[#D68060] text-white";
      case "medium":
        return "bg-[#D49B6A] text-white";
      case "positive":
        return "bg-[#395B64] text-white";
      default:
        return "bg-[#7F8C8D] text-white";
    }
  };

  const getImpactBarColor = (impact: string) => {
