import React, { useState, useEffect } from "react";
import {
  Sparkles,
  X,
  Play,
  Pause,
  RotateCcw,
  ArrowRight,
  CheckCircle2,
  AlertTriangle,
  HeartHandshake,
  Activity,
  Cpu,
  UserCheck,
  TrendingDown,
  TrendingUp,
  ShieldCheck
} from "lucide-react";

interface Props {
  isOpen: boolean;
  onClose: () => void;
  onJumpToParticipant?: (id: string) => void;
}

interface DemoStep {
  stepNumber: number;
  stageTitle: string;
  badge: string;
  badgeColor: string;
  dayLabel: string;
  score: number;
  rateOfChange: string;
  headline: string;
  description: string;
  xaiFactor: string;
  humanAction: string;
  stateIcon: "stable" | "warning" | "alert" | "review" | "support" | "recovering";
}

const DEMO_STEPS: DemoStep[] = [
  {
    stepNumber: 1,
    stageTitle: "Baseline Routine",
    badge: "Day 1: Baseline",
    badgeColor: "bg-[#395B64] text-white",
    dayLabel: "Day 1",
    score: 28,
    rateOfChange: "0 pts",
    headline: "Participant P-1053 completes initial reflection",
    description: "Voluntary check-in reports calm mood, good sleep (4/5), and stable surroundings. Trajectory classified as Stable.",
    xaiFactor: "All indicators within balanced thresholds.",
    humanAction: "Routine voluntary monitoring active.",
    stateIcon: "stable"
  },
  {
    stepNumber: 2,
    stageTitle: "Early Stress Signal",
    badge: "Day 2: Stress Rise",
    badgeColor: "bg-[#D49B6A] text-white",
    dayLabel: "Day 2",
    score: 44,
    rateOfChange: "+16 pts",
    headline: "Elevated tension and daily pressure reported",
    description: "Stress increases to 4/5 due to shelter transition. Moving average shifts upward.",
    xaiFactor: "Stress indicator contributed 65% of daily score delta.",
    humanAction: "Dashboard flags gradual increase for background monitoring.",
    stateIcon: "warning"
  },
  {
    stepNumber: 3,
    stageTitle: "Sleep Disruption",
    badge: "Day 3: Sleep Deterioration",
    badgeColor: "bg-[#D68060] text-white",
    dayLabel: "Day 3",
    score: 62,
    rateOfChange: "+18 pts",
    headline: "Persistent insomnia and restless nights reported",
    description: "Sleep quality drops to 1/5. Consecutive worsening reaches 2 check-ins. Rate of change reaches +17 pts/step.",
    xaiFactor: "Compound effect of high stress (4/5) + severe sleep disruption (1/5).",
    humanAction: "Early-warning forecast predicts potential need for proactive counselor contact.",
    stateIcon: "warning"
  },
  {
    stepNumber: 4,
    stageTitle: "Safety Uncertainty",
    badge: "Day 4: Environment Uncertainty",
    badgeColor: "bg-[#D68060] text-white",
    dayLabel: "Day 4",
    score: 76,
    rateOfChange: "+14 pts",
    headline: "Participant reports feeling unsure about environmental safety",
    description: "Safety response shifts from 'Mostly' to 'Unsure'. Social connection drops to 2/5 (isolated).",
    xaiFactor: "Perceived safety uncertainty contributes +16% weight to distress indicator.",
    humanAction: "Trajectory engine upgrades classification to 'Gradually Increasing' with high urgency.",
    stateIcon: "alert"
  },
  {
    stepNumber: 5,
    stageTitle: "Voluntary Support Request",
    badge: "Day 5: Support Requested",
    badgeColor: "bg-[#2C3639] text-[#A5C9CA]",
    dayLabel: "Day 5",
    score: 84,
    rateOfChange: "+8 pts",
    headline: "Participant selects 'Yes, please have a counselor reach out'",
    description: "High distress indicator (84/100) paired with direct support request. High-priority alert triggered.",
    xaiFactor: "Explicit human support request (+10%) alongside compound stress, sleep, and safety drivers.",
    humanAction: "Case dispatched to Support Worker Review Queue with full explainability breakdown.",
    stateIcon: "alert"
  },
  {
    stepNumber: 6,
    stageTitle: "Explainable AI Synthesis",
    badge: "AI Trajectory Analysis",
    badgeColor: "bg-[#395B64] text-white",
    dayLabel: "Day 5",
    score: 84,
    rateOfChange: "+56 pts over 5 days",
    headline: "AURA generates transparent reasoning report",
    description: "Why did AURA generate this signal? 38% Stress, 26% Sleep, 20% Safety Uncertainty, 16% Isolation.",
    xaiFactor: "Transparent feature attribution shows exact weights to eliminate black-box guesswork.",
    humanAction: "Humanitarian worker reviews plain-language explanation and verifies historical trajectory.",
    stateIcon: "review"
  },
  {
    stepNumber: 7,
    stageTitle: "Human Support Intervention",
    badge: "Humanitarian Care",
    badgeColor: "bg-[#395B64] text-[#A5C9CA]",
    dayLabel: "Day 5 (Afternoon)",
    score: 84,
    rateOfChange: "Intervention active",
    headline: "Dr. Sarah Jenkins conducts 1-on-1 supportive conversation",
    description: "Support worker conducts private check-in, explores shelter noise issues, and introduces 4-4-4 grounding.",
    xaiFactor: "Suggested Support Plan provided conversation focus points tailored to sleep and safety.",
    humanAction: "Intervention logged in audit trail: 'Support conversation & grounding resources provided'.",
    stateIcon: "support"
  },
  {
    stepNumber: 8,
    stageTitle: "Post-Intervention Reflection",
    badge: "Day 7: Follow-up",
    badgeColor: "bg-emerald-700 text-white",
    dayLabel: "Day 7",
    score: 48,
    rateOfChange: "-36 pts",
    headline: "Participant records improved sleep and renewed calmness",
    description: "Sleep improves to 4/5, stress drops to 2/5, and participant feels connected to community center.",
    xaiFactor: "Distress indicator dropped by -36 points following human counselor intervention.",
    humanAction: "Outcome verified: 'Positive recovery post-intervention'. Case moved to Stable monitoring.",
    stateIcon: "recovering"
  }
];

export const LiveDemonstrationModal: React.FC<Props> = ({
  isOpen,
  onClose,
  onJumpToParticipant
}) => {
  const [currentStepIdx, setCurrentStepIdx] = useState(0);
  const [isPlaying, setIsPlaying] = useState(true);

  useEffect(() => {
    if (!isOpen) {
      setCurrentStepIdx(0);
      setIsPlaying(false);
      return;
    }

    let interval: any = null;
    if (isPlaying) {
      interval = setInterval(() => {
        setCurrentStepIdx(prev => (prev + 1) % DEMO_STEPS.length);
      }, 4200);
    }
    return () => {
      if (interval) clearInterval(interval);
    };
  }, [isOpen, isPlaying]);

  if (!isOpen) return null;

  const currentStep = DEMO_STEPS[currentStepIdx];
  const progressPercent = ((currentStepIdx + 1) / DEMO_STEPS.length) * 100;

  return (
    <div className="fixed inset-0 z-50 bg-black/80 backdrop-blur-md flex items-center justify-center p-4 sm:p-6 overflow-y-auto">
      <div className="bg-[#1C2321] border border-white/15 text-white rounded-3xl max-w-4xl w-full shadow-2xl overflow-hidden flex flex-col max-h-[92vh]">
        {/* Top Control Bar */}
        <div className="p-4 sm:p-6 bg-[#2C3639] border-b border-white/10 flex items-center justify-between">
          <div className="flex items-center space-x-3">
            <div className="w-10 h-10 rounded-2xl bg-[#A5C9CA]/20 text-[#A5C9CA] flex items-center justify-center">
              <Sparkles size={22} />
            </div>
            <div>
              <div className="flex items-center space-x-2">
                <span className="text-[10px] font-black uppercase tracking-wider px-2 py-0.5 rounded-full bg-[#A5C9CA]/20 text-[#A5C9CA]">
                  SIH Demonstration Sequence
                </span>
                <span className="font-mono text-xs text-[#E7EDEA]/70">
                  Case Study: P-1053
                </span>
              </div>
              <h2 className="text-lg sm:text-xl font-black text-white">
                Live AI Trajectory & Human Intervention Walkthrough
              </h2>
            </div>
          </div>

          <button
            onClick={onClose}
            className="p-2 rounded-xl bg-white/10 hover:bg-white/20 text-white transition-colors cursor-pointer"
          >
            <X size={20} />
          </button>
        </div>

        {/* Progress Tracker Bar */}
        <div className="w-full bg-white/5 h-1.5">
          <div
            className="h-full bg-gradient-to-r from-[#A5C9CA] to-[#D68060] transition-all duration-500"
            style={{ width: `${progressPercent}%` }}
          ></div>
        </div>

        {/* Step Indicator Pills */}
        <div className="px-6 py-3 bg-[#1C2321] border-b border-white/10 overflow-x-auto flex items-center space-x-2 scrollbar-none">
          {DEMO_STEPS.map((s, idx) => (
            <button
              key={idx}
              onClick={() => {
                setCurrentStepIdx(idx);
                setIsPlaying(false);
              }}
              className={`px-3 py-1.5 rounded-xl text-xs font-bold whitespace-nowrap transition-all cursor-pointer flex items-center space-x-1.5 ${
                idx === currentStepIdx
                  ? "bg-[#A5C9CA] text-[#2C3639] shadow-sm font-black scale-105"
                  : idx < currentStepIdx
                  ? "bg-white/15 text-[#E7EDEA]"
                  : "bg-white/5 text-[#E7EDEA]/50 hover:bg-white/10"
              }`}
            >
              <span>{idx + 1}. {s.dayLabel}</span>
            </button>
          ))}
        </div>

        {/* Main Stage Presentation Area */}
        <div className="p-6 sm:p-8 flex-1 overflow-y-auto space-y-6">
          {/* Main Visual Card */}
