                className="px-5 py-2 rounded-xl bg-emerald-500 hover:bg-emerald-600 text-white text-xs font-black transition-colors flex items-center space-x-1.5 cursor-pointer"
              >
                <CheckCircle2 size={15} />
                <span>Inspect Case P-1053 in App</span>
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

