import React, { useState } from "react";
import {
  Sparkles,
  RotateCcw,
  CheckCircle2,
  ChevronDown,
  ChevronUp,
  Presentation,
  Play,
  ArrowRight,
  ShieldCheck,
  Check
} from "lucide-react";

interface Props {
  onResetDemo: () => void;
  onOpenLiveDemo: () => void;
  onNavigate: (view: string) => void;
  onSelectParticipant?: (id: string) => void;
}

export const PresenterModeBar: React.FC<Props> = ({
  onResetDemo,
  onOpenLiveDemo,
  onNavigate,
  onSelectParticipant
}) => {
  const [expanded, setExpanded] = useState(false);
  const [completedSteps, setCompletedSteps] = useState<number[]>([]);
  const [resetToast, setResetToast] = useState(false);

  const steps = [
    { num: 1, text: "Participant signs up", targetView: "signup" },
    { num: 2, text: "Participant gives consent", targetView: "signup" },
    { num: 3, text: "Participant completes check-in", targetView: "checkin" },
    { num: 4, text: "AI generates wellbeing signal", targetView: "checkin" },
    { num: 5, text: "Dashboard receives new data", targetView: "dashboard" },
    { num: 6, text: "Trajectory begins increasing", targetView: "detail", participantId: "P-1053" },
    { num: 7, text: "Explainable AI identifies contributing indicators", targetView: "detail", participantId: "P-1053" },
    { num: 8, text: "Early-warning forecast appears", targetView: "detail", participantId: "P-1053" },
    { num: 9, text: "Support worker receives follow-up alert", targetView: "alerts" },
    { num: 10, text: "Human reviews the signal", targetView: "alerts" },
    { num: 11, text: "Support intervention is recorded", targetView: "followups" },
    { num: 12, text: "Follow-up check-in occurs", targetView: "followups" },
    { num: 13, text: "Indicator improves (Recovery trend)", targetView: "followups" },
    { num: 14, text: "Community dashboard updates anonymously", targetView: "community" }
  ];

  const toggleStep = (num: number) => {
    setCompletedSteps(prev =>
      prev.includes(num) ? prev.filter(n => n !== num) : [...prev, num]
    );
  };

  const handleStepJump = (step: typeof steps[0]) => {
    if (!completedSteps.includes(step.num)) {
      setCompletedSteps(prev => [...prev, step.num]);
    }
    if (step.participantId && onSelectParticipant) {
      onSelectParticipant(step.participantId);
    }
    onNavigate(step.targetView);
  };

  const handleReset = () => {
    onResetDemo();
    setCompletedSteps([]);
    setResetToast(true);
    setTimeout(() => setResetToast(false), 3000);
  };

  return (
    <div className="bg-[#2C3639] border-b border-white/10 text-white transition-all">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-2">
        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-3">
            <span className="flex items-center space-x-1.5 px-2.5 py-0.5 rounded-full bg-[#A5C9CA]/20 text-[#A5C9CA] text-[10px] font-black uppercase tracking-wider">
              <Presentation size={12} />
              <span>SIH Presenter Mode</span>
            </span>

            <button
              onClick={() => setExpanded(!expanded)}
              className="text-xs font-bold text-[#E7EDEA]/90 hover:text-white flex items-center space-x-1 cursor-pointer"
            >
              <span>14-Step Presentation Script ({completedSteps.length}/14)</span>
              {expanded ? <ChevronUp size={14} /> : <ChevronDown size={14} />}
            </button>
          </div>

          <div className="flex items-center space-x-2">
            <button
              onClick={onOpenLiveDemo}
              className="px-3 py-1 rounded-lg bg-[#A5C9CA] hover:bg-[#8bb4b5] text-[#2C3639] text-xs font-black transition-all flex items-center space-x-1.5 cursor-pointer shadow-xs"
            >
              <Sparkles size={13} />
              <span>🚀 Live AI Demo</span>
            </button>

            <button
              onClick={handleReset}
              className="px-3 py-1 rounded-lg bg-white/10 hover:bg-white/20 text-[#E7EDEA] text-xs font-bold transition-all flex items-center space-x-1.5 cursor-pointer"
              title="Reset all synthetic data to baseline"
            >
              <RotateCcw size={13} />
              <span>Reset Demo</span>
            </button>
          </div>
        </div>

        {resetToast && (
          <div className="my-2 p-2 rounded-xl bg-[#395B64] text-xs text-white font-bold flex items-center space-x-2">
            <Check size={14} className="text-[#A5C9CA]" />
            <span>All synthetic participants, check-ins, and alerts reset to pristine demonstration state.</span>
          </div>
        )}

        {/* Expanded 14-Step Guide Drawer */}
        {expanded && (
          <div className="mt-3 pt-3 border-t border-white/10 space-y-3 pb-2">
            <p className="text-[11px] text-[#E7EDEA]/70">
              Click any step below to jump directly into that part of the demonstration flow:
            </p>

            <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-2">
              {steps.map((step) => {
                const isDone = completedSteps.includes(step.num);
                return (
                  <div
                    key={step.num}
                    className={`p-2 rounded-xl border flex items-center justify-between text-xs transition-colors ${
                      isDone
                        ? "bg-[#395B64]/50 border-[#A5C9CA]/40 text-white"
                        : "bg-white/5 border-white/10 text-[#E7EDEA]/80 hover:bg-white/10"
                    }`}
                  >
                    <button
                      onClick={() => toggleStep(step.num)}
                      className="flex items-center space-x-2 cursor-pointer text-left flex-1"
                    >
                      <span className={`w-4 h-4 rounded-full flex items-center justify-center text-[10px] font-bold ${
                        isDone ? "bg-[#A5C9CA] text-[#2C3639]" : "bg-white/20 text-white"
                      }`}>
                        {isDone ? "✓" : step.num}
                      </span>
                      <span className="line-clamp-1">{step.text}</span>
                    </button>

                    <button
                      onClick={() => handleStepJump(step)}
                      className="ml-2 p-1 rounded-md bg-white/10 hover:bg-[#A5C9CA] hover:text-[#2C3639] text-[#E7EDEA] transition-colors cursor-pointer"
                      title="Jump to screen"
                    >
                      <ArrowRight size={12} />
                    </button>
                  </div>
                );
              })}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

