import React, { useState } from "react";
import {
  HeartHandshake,
  UserPlus,
  CalendarPlus,
  CheckCircle2,
  BookOpen,
  Users,
  Sparkles,
  ShieldCheck,
  Check,
  UserCheck,
  Info
} from "lucide-react";
import { SupportRecommendation, Participant } from "../types";

interface Props {
  recommendation?: SupportRecommendation | null;
  plan?: SupportRecommendation | null;
  participant?: Participant | null;
  participantId?: string;
  onAssignWorker?: (idOrName: string, name?: string) => void;
  onCreateFollowUp?: (type: string, focus: string) => void;
  onScheduleFollowUp?: (participantId: string, date: string, reason: string) => void;
}

export const SuggestedSupportPlanCard: React.FC<Props> = ({
  recommendation,
  plan,
  participant,
  participantId,
  onAssignWorker,
  onCreateFollowUp,
  onScheduleFollowUp
}) => {
  // Support either 'recommendation' or 'plan' prop
  const activePlan = recommendation || plan || null;
  const pId = participant?.id || participantId || "Participant";
  const initialWorker = participant?.assignedWorker || "";

  const [assigned, setAssigned] = useState(initialWorker);
  const [showAssignModal, setShowAssignModal] = useState(false);
  const [showFollowUpModal, setShowFollowUpModal] = useState(false);
  const [workerInput, setWorkerInput] = useState(initialWorker || "Dr. Sarah Jenkins, MSW");
  const [followUpType, setFollowUpType] = useState("Support conversation");
  const [followUpFocus, setFollowUpFocus] = useState(
    activePlan?.conversationFocus || "General wellbeing check-in and grounding"
  );
  const [followUpDate, setFollowUpDate] = useState(
    new Date(Date.now() + 86400000 * 2).toISOString().split("T")[0]
  );
  const [actionSuccess, setActionSuccess] = useState<string | null>(null);

  const handleConfirmAssign = () => {
    if (!workerInput.trim()) return;
    setAssigned(workerInput.trim());

    if (onAssignWorker) {
      if (participant?.id) {
        // If it's a 2-arg function (participantId, workerName)
        onAssignWorker(participant.id, workerInput.trim());
      } else if (participantId) {
        onAssignWorker(participantId, workerInput.trim());
      } else {
        onAssignWorker(workerInput.trim());
      }
    }

    setShowAssignModal(false);
    setActionSuccess(`Support worker ${workerInput.trim()} assigned to case.`);
    setTimeout(() => setActionSuccess(null), 3500);
  };

  const handleConfirmFollowUp = () => {
    if (onScheduleFollowUp && (participant?.id || participantId)) {
      onScheduleFollowUp(participant?.id || participantId || "", followUpDate, `${followUpType}: ${followUpFocus}`);
    } else if (onCreateFollowUp) {
      onCreateFollowUp(followUpType, followUpFocus);
    }
    setShowFollowUpModal(false);
    setActionSuccess(`Intervention follow-up scheduled for ${followUpDate}: "${followUpType}".`);
    setTimeout(() => setActionSuccess(null), 3500);
  };

  return (
    <div className="bg-white rounded-3xl border border-[#E7EDEA] p-6 sm:p-7 shadow-xs space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 border-b border-[#E7EDEA] pb-5">
        <div className="flex items-center space-x-3">
          <div className="w-11 h-11 rounded-2xl bg-[#A5C9CA]/30 text-[#395B64] flex items-center justify-center">
            <HeartHandshake size={22} />
          </div>
          <div>
            <span className="text-[10px] font-black uppercase tracking-wider px-2 py-0.5 rounded-full bg-[#A5C9CA]/20 text-[#395B64]">
              Decision Support
            </span>
            <h3 className="text-xl font-black text-[#2C3639] mt-0.5">
              Suggested Support Plan
            </h3>
          </div>
        </div>

        <div className="flex items-center space-x-2">
          {assigned ? (
            <span className="text-xs font-bold text-[#395B64] px-3 py-1 rounded-xl bg-[#A5C9CA]/20 border border-[#A5C9CA]/40 flex items-center">
              <CheckCircle2 size={14} className="mr-1.5" />
              Assigned: {assigned}
            </span>
          ) : (
            <span className="text-xs font-semibold text-[#7F8C8D] px-3 py-1 rounded-xl bg-[#F9FBFA] border border-[#E7EDEA] flex items-center">
              <Info size={13} className="mr-1.5 text-[#7F8C8D]" />
              No support worker assigned
            </span>
          )}
        </div>
      </div>

      {actionSuccess && (
        <div className="p-3.5 rounded-2xl bg-[#A5C9CA]/20 border border-[#395B64]/30 text-xs font-bold text-[#395B64] flex items-center space-x-2">
          <Check size={16} />
          <span>{actionSuccess}</span>
        </div>
      )}

      {/* Plan Details Grid or Empty State */}
      {activePlan ? (
        <div className="grid md:grid-cols-2 gap-5">
          {/* Primary Consideration & Suggested Focus */}
          <div className="space-y-4">
            <div className="p-4 rounded-2xl bg-[#F9FBFA] border border-[#E7EDEA]">
              <span className="text-[11px] font-bold text-[#7F8C8D] uppercase tracking-wider block mb-1">
                Primary Consideration
              </span>
              <p className="text-sm font-black text-[#2C3639]">
                {activePlan.primaryRecommendation || "Continue voluntary routine monitoring."}
              </p>
              {activePlan.rationale && (
                <p className="text-xs text-[#5A6B6D] mt-1.5 leading-relaxed">
                  <strong>Rationale:</strong> {activePlan.rationale}
                </p>
              )}
            </div>

            <div className="p-4 rounded-2xl bg-[#F9FBFA] border border-[#E7EDEA]">
              <span className="text-[11px] font-bold text-[#7F8C8D] uppercase tracking-wider block mb-1">
                Suggested Conversation Focus
              </span>
              <p className="text-xs font-bold text-[#395B64] leading-relaxed">
                "{activePlan.conversationFocus || "General wellbeing check-in and grounding"}"
              </p>
            </div>
          </div>

          {/* Recommended Resources */}
          <div className="p-4 rounded-2xl bg-[#F9FBFA] border border-[#E7EDEA] flex flex-col justify-between">
            <div>
              <span className="text-[11px] font-bold text-[#7F8C8D] uppercase tracking-wider block mb-2">
                Optional Support Resources
              </span>
              {activePlan.resources && activePlan.resources.length > 0 ? (
                <ul className="space-y-2">
                  {activePlan.resources.map((res, i) => (
                    <li key={i} className="flex items-start space-x-2 text-xs text-[#2C3639]">
                      <span className="w-1.5 h-1.5 rounded-full bg-[#395B64] mt-1.5 shrink-0"></span>
                      <span>{res}</span>
                    </li>
                  ))}
                </ul>
              ) : (
                <p className="text-xs text-[#7F8C8D] italic">
                  Standard grounding and voluntary counseling resources available.
                </p>
              )}
            </div>

            <div className="mt-4 pt-3 border-t border-[#E7EDEA] text-[11px] text-[#7F8C8D]">
              Voluntary participant resources — not clinical prescriptions.
            </div>
          </div>
        </div>
      ) : (
        <div className="p-6 rounded-2xl bg-[#F9FBFA] border border-[#E7EDEA] text-center space-y-2">
          <p className="text-xs font-bold text-[#2C3639]">
            No support plan has been generated yet.
          </p>
          <p className="text-[11px] text-[#7F8C8D]">
            A suggested plan will be created automatically once check-in reflections or human review signals are received.
          </p>
        </div>
      )}

      {/* Action Buttons */}
      <div className="flex flex-wrap items-center justify-between gap-3 pt-2">
        <div className="flex flex-wrap items-center gap-3">
          <button
            onClick={() => setShowAssignModal(true)}
            className="px-4 py-2.5 rounded-2xl bg-[#395B64] hover:bg-[#2C3639] text-white text-xs font-bold transition-colors flex items-center space-x-2 shadow-xs cursor-pointer"
          >
            <UserPlus size={15} />
            <span>{assigned ? "Reassign Worker" : "Assign Support Worker"}</span>
          </button>

          <button
            onClick={() => setShowFollowUpModal(true)}
            className="px-4 py-2.5 rounded-2xl bg-[#F9FBFA] hover:bg-[#E7EDEA] text-[#2C3639] border border-[#E7EDEA] text-xs font-bold transition-colors flex items-center space-x-2 cursor-pointer"
          >
            <CalendarPlus size={15} />
            <span>Create Follow-up</span>
          </button>
        </div>

        <span className="text-[11px] text-[#7F8C8D] italic">
          The human support worker makes the final decision on all actions.
        </span>
      </div>

      {/* Assign Worker Modal */}
      {showAssignModal && (
        <div className="fixed inset-0 z-50 bg-black/40 backdrop-blur-xs flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl p-6 max-w-md w-full shadow-xl space-y-4">
            <h4 className="text-lg font-black text-[#2C3639]">
              Assign Support Worker
            </h4>
            <p className="text-xs text-[#5A6B6D]">
              Assign a trained humanitarian case worker to monitor {pId} and coordinate follow-up.
            </p>
            <div>
              <label className="text-xs font-bold text-[#2C3639] block mb-1.5">
                Support Worker Name & Credentials
              </label>
              <input
                type="text"
                value={workerInput}
                onChange={(e) => setWorkerInput(e.target.value)}
                placeholder="e.g. Dr. Sarah Jenkins, MSW"
                className="w-full px-4 py-2.5 rounded-xl border border-[#E7EDEA] text-sm focus:outline-none focus:border-[#395B64]"
              />
            </div>
            <div className="flex justify-end space-x-2 pt-2">
              <button
                onClick={() => setShowAssignModal(false)}
                className="px-4 py-2 rounded-xl text-xs font-bold text-[#7F8C8D] hover:bg-[#F9FBFA]"
              >
                Cancel
              </button>
              <button
                onClick={handleConfirmAssign}
                className="px-4 py-2 rounded-xl text-xs font-bold bg-[#395B64] text-white hover:bg-[#2C3639]"
              >
                Confirm Assignment
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Create Follow-Up Modal */}
      {showFollowUpModal && (
        <div className="fixed inset-0 z-50 bg-black/40 backdrop-blur-xs flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl p-6 max-w-md w-full shadow-xl space-y-4">
            <h4 className="text-lg font-black text-[#2C3639]">
              Create Intervention Follow-up
            </h4>
            <p className="text-xs text-[#5A6B6D]">
              Log a planned human intervention to measure subsequent changes in distress indicators.
            </p>
            <div>
              <label className="text-xs font-bold text-[#2C3639] block mb-1">
                Intervention Type
              </label>
              <select
                value={followUpType}
                onChange={(e) => setFollowUpType(e.target.value)}
                className="w-full px-4 py-2.5 rounded-xl border border-[#E7EDEA] text-sm focus:outline-none focus:border-[#395B64]"
              >
                <option value="Support conversation">Support conversation</option>
                <option value="Resource referral">Resource referral & guidance</option>
                <option value="Safety check & grounding">Safety check & grounding</option>
                <option value="Peer community connection">Peer community connection</option>
              </select>
            </div>
            <div>
              <label className="text-xs font-bold text-[#2C3639] block mb-1">
                Target Date
              </label>
              <input
                type="date"
                value={followUpDate}
                onChange={(e) => setFollowUpDate(e.target.value)}
                className="w-full px-4 py-2.5 rounded-xl border border-[#E7EDEA] text-sm focus:outline-none focus:border-[#395B64]"
              />
            </div>
            <div>
              <label className="text-xs font-bold text-[#2C3639] block mb-1">
                Conversation Focus
              </label>
              <input
                type="text"
                value={followUpFocus}
                onChange={(e) => setFollowUpFocus(e.target.value)}
                className="w-full px-4 py-2.5 rounded-xl border border-[#E7EDEA] text-sm focus:outline-none focus:border-[#395B64]"
              />
            </div>
            <div className="flex justify-end space-x-2 pt-2">
              <button
                onClick={() => setShowFollowUpModal(false)}
                className="px-4 py-2 rounded-xl text-xs font-bold text-[#7F8C8D] hover:bg-[#F9FBFA]"
              >
                Cancel
              </button>
              <button
                onClick={handleConfirmFollowUp}
                className="px-4 py-2 rounded-xl text-xs font-bold bg-[#395B64] text-white hover:bg-[#2C3639]"
              >
                Schedule Follow-up
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from "react";
import { Mic, Square, Play, Pause, RotateCcw, Trash2, Edit3, Check, ChevronDown, ChevronUp, Shield, Cpu, Info, Volume2, Sparkles, FileText } from "lucide-react";
import { voiceRecordingService } from "../services/voiceRecording";
import { analyzeReflection } from "../services/reflectionAnalysis";
import { ReflectionAnalysis } from "./ReflectionAnalysis";
import { ParticipantReflection } from "../types";

interface VoiceRecorderProps {
  participantId: string;
  onSaveReflection: (reflection: ParticipantReflection | null) => void;
  onClearReflection: () => void;
  initialTranscript?: string;
  onSkip?: () => void;
}

export const VoiceRecorder: React.FC<VoiceRecorderProps> = ({
  participantId,
  onSaveReflection,
  onClearReflection,
  initialTranscript = "",
  onSkip
}) => {
  // Mode & Recording State
  const [mode, setMode] = useState<"choice" | "voice" | "text">("choice");
  const [showPrivacyNotice, setShowPrivacyNotice] = useState(false);
  const [isRecording, setIsRecording] = useState(false);
  const [recordingSeconds, setRecordingSeconds] = useState(0);
  const [transcript, setTranscript] = useState(initialTranscript);
  const [interimText, setInterimText] = useState("");
  const [isEditingTranscript, setIsEditingTranscript] = useState(false);
  const [audioUrl, setAudioUrl] = useState<string | null>(null);
  const [isPlayingAudio, setIsPlayingAudio] = useState(false);
  const [shareWithWorker, setShareWithWorker] = useState(true);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [isDemoSample, setIsDemoSample] = useState(false);

  // Expandable info cards
  const [showWhyCard, setShowWhyCard] = useState(false);
  const [showHowItWorksCard, setShowHowItWorksCard] = useState(false);

  const audioRef = useRef<HTMLAudioElement | null>(null);

  // Speech recognition compatibility check
  const isSpeechRecognitionSupported = voiceRecordingService.isSpeechRecognitionSupported();

  // Re-run dynamic analysis whenever transcript changes
  const analysisResult = analyzeReflection(transcript, isDemoSample);

  // Auto-sync reflection object to parent check-in
  useEffect(() => {
    if (transcript.trim().length > 0) {
      const refObj: ParticipantReflection = {
        id: `ref-${Date.now()}`,
        participantId,
        type: audioUrl ? "voice" : "text",
        transcript: transcript.trim(),
        submittedAt: new Date().toISOString(),
        audioRecorded: !!audioUrl,
        shareWithWorker,
        analysis: analysisResult
      };
      onSaveReflection(refObj);
    } else {
      onSaveReflection(null);
    }
  }, [transcript, audioUrl, shareWithWorker, isDemoSample]);

  // Handle start voice trigger
  const handleInitiateVoice = () => {
    setShowPrivacyNotice(true);
  };

  const handleConfirmPrivacyStartRecording = async () => {
    setShowPrivacyNotice(false);
    setMode("voice");
    setIsRecording(true);
    setErrorMessage(null);
    setTranscript("");
    setInterimText("");
    setIsDemoSample(false);

    const started = await voiceRecordingService.startRecording(
      (finalText, interim) => {
        setTranscript(finalText);
        setInterimText(interim);
      },
      (seconds) => {
        setRecordingSeconds(seconds);
      },
      (err) => {
        setErrorMessage(err);
        setIsRecording(false);
      }
    );

    if (!started) {
      setIsRecording(false);
    }
  };

  const handleStopRecording = async () => {
    setIsRecording(false);
    const { audioUrl: url } = await voiceRecordingService.stopRecording();
    setAudioUrl(url);
  };

  const handleTogglePlayAudio = () => {
    if (!audioUrl) return;

    if (!audioRef.current) {
      audioRef.current = new Audio(audioUrl);
      audioRef.current.onended = () => setIsPlayingAudio(false);
    }

    if (isPlayingAudio) {
      audioRef.current.pause();
      setIsPlayingAudio(false);
    } else {
      audioRef.current.play();
      setIsPlayingAudio(true);
    }
  };

  const handleRecordAgain = async () => {
    if (audioRef.current) {
      audioRef.current.pause();
      audioRef.current = null;
    }
    setAudioUrl(null);
    setIsPlayingAudio(false);
    handleConfirmPrivacyStartRecording();
  };

  const handleDeleteRecording = () => {
    if (audioRef.current) {
      audioRef.current.pause();
      audioRef.current = null;
    }
    voiceRecordingService.cleanup();
    setAudioUrl(null);
    setIsPlayingAudio(false);
    setTranscript("");
    setInterimText("");
    setIsDemoSample(false);
    onClearReflection();
  };

  // Demo synthetic sample loader (only for presenter / demo mode)
  const handleLoadDemoSample = () => {
    setMode("text");
    setIsDemoSample(true);
    setTranscript("I haven't been sleeping well since moving to the new shelter block. The nighttime noise makes me feel tense and overwhelmed.");
  };

  const formatTime = (secs: number) => {
    const mins = Math.floor(secs / 60);
    const remainingSecs = secs % 60;
    return `${mins.toString().padStart(2, "0")}:${remainingSecs.toString().padStart(2, "0")}`;
  };

  return (
    <div className="space-y-6">
      {/* Privacy Notice Modal/Banner */}
      {showPrivacyNotice && (
        <div className="p-5 rounded-2xl bg-[#F9FBFA] border-2 border-[#395B64] space-y-4 animate-in fade-in duration-200">
          <div className="flex items-center space-x-2 text-[#395B64]">
            <Shield size={18} />
            <h4 className="text-sm font-black uppercase tracking-wide text-[#2C3639]">
              Before You Record
            </h4>
          </div>

          <ul className="text-xs text-[#5A6B6D] space-y-2 leading-relaxed">
            <li className="flex items-start space-x-2">
              <span className="text-[#395B64] font-bold">•</span>
              <span>Your microphone will be active <strong>only while you choose to record</strong>.</span>
            </li>
            <li className="flex items-start space-x-2">
              <span className="text-[#395B64] font-bold">•</span>
              <span>You can pause, edit your transcript, re-record, or completely delete the audio at any time.</span>
            </li>
            <li className="flex items-start space-x-2">
              <span className="text-[#395B64] font-bold">•</span>
              <span>For this prototype, speech-to-text processing occurs in your browser.</span>
            </li>
            <li className="flex items-start space-x-2">
              <span className="text-[#395B64] font-bold">•</span>
              <span><strong>Privacy Reminder:</strong> Please do not include full names, exact shelter room numbers, or sensitive government IDs in your reflection.</span>
            </li>
          </ul>

          <div className="flex items-center space-x-3 pt-2">
            <button
              onClick={handleConfirmPrivacyStartRecording}
              className="px-5 py-2.5 rounded-xl bg-[#395B64] hover:bg-[#2C3639] text-white text-xs font-bold transition-all shadow-xs cursor-pointer flex items-center space-x-2"
            >
              <Mic size={14} />
              <span>I Understand — Start Recording</span>
            </button>
            <button
              onClick={() => setShowPrivacyNotice(false)}
              className="px-4 py-2.5 rounded-xl border border-[#E7EDEA] bg-white text-[#7F8C8D] hover:text-[#2C3639] text-xs font-bold transition-all cursor-pointer"
            >
              Cancel
            </button>
          </div>
        </div>
      )}

      {/* Main Interaction Area */}
      <div className="p-5 sm:p-6 rounded-3xl bg-[#F9FBFA] border border-[#E7EDEA] space-y-5">
        <div className="flex items-center justify-between flex-wrap gap-2">
          <div className="flex items-center space-x-2">
            <Mic size={16} className="text-[#395B64]" />
            <span className="text-xs font-black uppercase text-[#2C3639]">
              Optional Reflection Input
            </span>
          </div>
          <span className="text-[11px] font-bold text-emerald-700 bg-emerald-50 border border-emerald-200 px-2.5 py-0.5 rounded-lg">
            Optional • Voice or Text
          </span>
        </div>

        {/* Browser capability status */}
        {!isSpeechRecognitionSupported && (
          <div className="p-3 rounded-xl bg-amber-50 border border-amber-200 text-xs text-amber-800 flex items-start space-x-2">
            <Info size={14} className="mt-0.5 shrink-0 text-amber-600" />
            <p>
              Live speech-to-text recognition is not supported in this browser. You can record audio directly or type your reflection below.
            </p>
          </div>
        )}

        {errorMessage && (
          <div className="p-3 rounded-xl bg-rose-50 border border-rose-200 text-xs text-rose-800">
            {errorMessage}
          </div>
        )}

        {/* Choice / Idle State */}
        {mode === "choice" && !transcript && (
          <div className="space-y-4">
            <p className="text-xs text-[#5A6B6D]">
              Choose how you would like to share your voluntary reflection:
            </p>

            <div className="grid sm:grid-cols-2 gap-3">
              <button
                onClick={handleInitiateVoice}
                className="p-4 rounded-2xl bg-white border border-[#E7EDEA] hover:border-[#395B64] hover:bg-white text-left transition-all group cursor-pointer shadow-xs"
              >
                <div className="flex items-center space-x-3 mb-2">
                  <div className="w-9 h-9 rounded-xl bg-[#395B64] text-white flex items-center justify-center group-hover:scale-105 transition-transform">
                    <Mic size={18} />
                  </div>
                  <div>
                    <h5 className="text-xs font-bold text-[#2C3639]">Start Voice Reflection</h5>
                    <span className="text-[10px] text-[#7F8C8D]">Speak naturally into microphone</span>
                  </div>
                </div>
                <p className="text-[11px] text-[#7F8C8D]">
                  Audio is recorded locally with assistive transcription where supported.
                </p>
              </button>

              <button
                onClick={() => setMode("text")}
                className="p-4 rounded-2xl bg-white border border-[#E7EDEA] hover:border-[#395B64] hover:bg-white text-left transition-all group cursor-pointer shadow-xs"
              >
                <div className="flex items-center space-x-3 mb-2">
                  <div className="w-9 h-9 rounded-xl bg-[#A5C9CA]/40 text-[#2C3639] flex items-center justify-center group-hover:scale-105 transition-transform">
                    <FileText size={18} />
                  </div>
                  <div>
                    <h5 className="text-xs font-bold text-[#2C3639]">Type a Reflection</h5>
                    <span className="text-[10px] text-[#7F8C8D]">Write in your own words</span>
                  </div>
                </div>
                <p className="text-[11px] text-[#7F8C8D]">
                  Enter free-form thoughts, feelings, or situational context.
                </p>
              </button>
            </div>

            {/* SIH Demonstration Helper */}
            <div className="pt-2 flex items-center justify-between border-t border-[#E7EDEA]">
              <span className="text-[10px] text-[#7F8C8D]">Presentation / Evaluator Tools:</span>
              <button
                onClick={handleLoadDemoSample}
                className="text-[11px] font-bold text-[#395B64] hover:text-[#2C3639] bg-white border border-[#E7EDEA] px-3 py-1 rounded-lg transition-colors flex items-center space-x-1 cursor-pointer"
              >
                <Sparkles size={12} className="text-amber-500" />
                <span>Load Demo Sample Reflection</span>
              </button>
            </div>
          </div>
        )}

        {/* Live Recording State */}
        {isRecording && (
          <div className="p-6 rounded-2xl bg-white border-2 border-[#395B64] text-center space-y-4">
            <div className="flex items-center justify-center space-x-2 text-[#D68060] font-black text-xs uppercase tracking-wider">
              <span className="w-2.5 h-2.5 rounded-full bg-rose-500 animate-ping"></span>
              <span>● Recording... {formatTime(recordingSeconds)}</span>
            </div>

            {/* Audio Wave Visualizer Simulation */}
            <div className="flex items-center justify-center space-x-1.5 h-10">
              <span className="w-1.5 h-4 bg-[#395B64] rounded-full animate-pulse"></span>
              <span className="w-1.5 h-8 bg-[#A5C9CA] rounded-full animate-bounce"></span>
              <span className="w-1.5 h-10 bg-[#395B64] rounded-full animate-pulse"></span>
              <span className="w-1.5 h-6 bg-[#D68060] rounded-full animate-bounce"></span>
              <span className="w-1.5 h-9 bg-[#395B64] rounded-full animate-pulse"></span>
              <span className="w-1.5 h-5 bg-[#A5C9CA] rounded-full animate-bounce"></span>
              <span className="w-1.5 h-3 bg-[#395B64] rounded-full animate-pulse"></span>
            </div>

            {/* Live Partial Transcript */}
            {(transcript || interimText) && (
              <div className="p-3 rounded-xl bg-[#F9FBFA] border border-[#E7EDEA] text-left text-xs text-[#2C3639] max-h-24 overflow-y-auto">
                <span className="font-semibold">{transcript}</span>{" "}
                <span className="text-[#7F8C8D] italic">{interimText}</span>
              </div>
            )}

            <button
              onClick={handleStopRecording}
              className="px-6 py-2.5 rounded-xl bg-[#D68060] hover:bg-[#c06e4f] text-white text-xs font-bold transition-all shadow-xs cursor-pointer inline-flex items-center space-x-2"
            >
              <Square size={13} />
              <span>Stop Recording</span>
            </button>
          </div>
        )}

        {/* Reviewing Recorded Voice or Typing */}
        {(transcript.length > 0 || mode === "text") && !isRecording && (
          <div className="space-y-4">
            {/* Demo Notice if synthetic sample */}
            {isDemoSample && (
              <div className="p-2.5 rounded-xl bg-amber-50 border border-amber-200 text-[11px] text-amber-900 flex items-center justify-between">
                <span className="font-bold flex items-center">
                  <Sparkles size={13} className="mr-1.5 text-amber-600" />
                  DEMO / SYNTHETIC DATA LOADED
                </span>
                <span className="text-[10px] uppercase font-bold text-amber-700">Presentation Mode</span>
              </div>
            )}

            {/* Audio Playback Controls if audio recorded */}
            {audioUrl && (
              <div className="p-3 rounded-2xl bg-white border border-[#E7EDEA] flex items-center justify-between flex-wrap gap-2">
                <div className="flex items-center space-x-3">
                  <button
                    onClick={handleTogglePlayAudio}
                    className="w-8 h-8 rounded-xl bg-[#395B64] text-white flex items-center justify-center hover:bg-[#2C3639] transition-colors cursor-pointer"
                  >
                    {isPlayingAudio ? <Pause size={14} /> : <Play size={14} className="ml-0.5" />}
                  </button>
                  <div className="text-xs">
                    <span className="font-bold text-[#2C3639] block">Your Audio Recording</span>
                    <span className="text-[10px] text-[#7F8C8D]">{formatTime(recordingSeconds)} length</span>
                  </div>
                </div>

                <div className="flex items-center space-x-2">
                  <button
                    onClick={handleRecordAgain}
                    className="px-2.5 py-1.5 rounded-lg border border-[#E7EDEA] text-[#5A6B6D] hover:text-[#2C3639] text-xs font-bold flex items-center space-x-1 cursor-pointer"
                  >
                    <RotateCcw size={12} />
                    <span>Record Again</span>
                  </button>
                  <button
                    onClick={handleDeleteRecording}
                    className="p-1.5 rounded-lg border border-[#E7EDEA] text-rose-600 hover:bg-rose-50 text-xs cursor-pointer"
                    title="Delete Recording"
                  >
                    <Trash2 size={13} />
                  </button>
                </div>
              </div>
            )}

            {/* Transcript & Text Editing */}
            <div className="space-y-2">
              <div className="flex items-center justify-between">
                <label className="text-[11px] font-bold uppercase tracking-wider text-[#7F8C8D] block">
                  {audioUrl ? "Transcript (Editable):" : "Reflection Text:"}
                </label>
                <div className="flex items-center space-x-2">
                  {mode === "text" && !audioUrl && (
                    <button
                      onClick={() => {
                        setMode("choice");
                        setTranscript("");
                        setIsDemoSample(false);
                      }}
                      className="text-[10px] text-[#7F8C8D] hover:text-[#2C3639] underline cursor-pointer"
                    >
                      Switch to Voice
                    </button>
                  )}
                  {transcript.length > 0 && (
                    <button
                      onClick={() => {
                        setTranscript("");
                        setIsDemoSample(false);
                      }}
                      className="text-[10px] text-rose-600 hover:text-rose-800 font-semibold cursor-pointer"
                    >
                      Clear Text
                    </button>
                  )}
                </div>
              </div>

              <textarea
                rows={3}
                value={transcript}
                onChange={(e) => {
                  setTranscript(e.target.value);
                  if (isDemoSample) setIsDemoSample(false);
                }}
                placeholder="Share your thoughts, feelings, or what happened today in your own words..."
                className="w-full p-3.5 rounded-2xl border border-[#E7EDEA] bg-white text-xs text-[#2C3639] focus:ring-2 focus:ring-[#395B64] focus:outline-none leading-relaxed"
              />
            </div>

            {/* Share with Worker Checkbox */}
