                      {new Date(log.timestamp).toLocaleTimeString([], {
                        hour: "2-digit",
                        minute: "2-digit",
                        second: "2-digit"
                      })}
                    </span>

                    <span
                      className={`text-[10px] font-bold px-2 py-0.5 rounded-md border uppercase tracking-wider ${getCategoryBadge(
                        log.category
                      )}`}
                    >
                      {formatActionName(log.action)}
                    </span>

                    <span className={`text-[10px] font-bold px-2 py-0.5 rounded-md ${getRoleBadge(log.actorRole)}`}>
                      {log.actorRole}
                    </span>

                    {log.participantId && (
                      <span className="font-mono text-xs font-black text-[#2C3639] bg-[#E7EDEA]/60 px-2 py-0.5 rounded-md">
                        {log.participantId}
                      </span>
                    )}

                    {isNew && (
                      <span className="text-[10px] font-bold bg-emerald-600 text-white px-2 py-0.5 rounded-full animate-bounce">
                        NEW
                      </span>
                    )}
                  </div>

                  <div className="flex items-center space-x-2 text-xs text-[#7F8C8D]">
                    <UserCheck size={14} className="text-[#395B64]" />
                    <span className="font-semibold text-[#2C3639]">{log.actorName || log.workerName || log.actorId}</span>
                    <span>•</span>
                    <span className="font-mono text-[11px]">{new Date(log.timestamp).toLocaleDateString()}</span>
                  </div>
                </div>

                <p className="text-xs text-[#5A6B6D] leading-relaxed pl-1 sm:pl-2">
                  {log.description || log.details}
                </p>

                {log.details && log.description && log.details !== log.description && (
                  <div className="text-[11px] text-[#7F8C8D] bg-[#F9FBFA] p-2 rounded-lg border border-[#E7EDEA]/60 ml-1 sm:ml-2 font-mono">
                    {log.details}
                  </div>
                )}
              </div>
            );
          })
        )}
      </div>
    </div>
  );
};
export default AuditLog;

