      {/* Filter and Search Bar */}
      <div className="flex flex-col sm:flex-row items-center justify-between gap-3">
        <div className="relative w-full sm:w-72">
          <Search size={16} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-[#7F8C8D]" />
          <input
            type="text"
            placeholder="Search participant ID, worker..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-9 pr-4 py-2 rounded-xl bg-white border border-[#E7EDEA] text-xs focus:outline-none focus:border-[#395B64]"
          />
        </div>

        <div className="flex items-center space-x-1.5 overflow-x-auto w-full sm:w-auto">
          {[
            { id: "all", label: "All Outcomes" },
            { id: "improving", label: "Improving" },
            { id: "no_change", label: "No Change" },
            { id: "worsening", label: "Worsening" },
            { id: "pending", label: "Pending" }
          ].map(tab => (
            <button
              key={tab.id}
              onClick={() => setFilterOutcome(tab.id)}
              className={`px-3 py-1.5 rounded-xl text-xs font-bold whitespace-nowrap transition-colors cursor-pointer ${
                filterOutcome === tab.id
                  ? "bg-[#395B64] text-white"
                  : "bg-white text-[#5A6B6D] border border-[#E7EDEA] hover:bg-[#F9FBFA]"
              }`}
            >
              {tab.label}
            </button>
          ))}
        </div>
      </div>

      {/* Follow-up Cases Grid */}
      <div className="grid gap-4">
        {filtered.map(fup => (
          <div
            key={fup.id}
            className="bg-white rounded-3xl border border-[#E7EDEA] p-6 shadow-xs hover:border-[#A5C9CA] transition-all space-y-4"
          >
            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 border-b border-[#E7EDEA] pb-3.5">
              <div className="flex items-center space-x-3">
                <button
                  onClick={() => onSelectParticipant(fup.participantId)}
                  className="font-mono text-sm font-black text-[#2C3639] hover:text-[#395B64] underline underline-offset-2 flex items-center space-x-1 cursor-pointer"
                >
                  <span>{fup.participantId}</span>
                  <ArrowRight size={14} />
                </button>

                <span className={`text-[10px] font-bold px-2.5 py-0.5 rounded-md border uppercase tracking-wider ${getOutcomeBadge(fup.outcome)}`}>
                  {fup.outcomeLabel}
                </span>
              </div>

              <div className="flex items-center space-x-3 text-xs text-[#7F8C8D]">
                <span className="flex items-center">
                  <UserCheck size={14} className="mr-1 text-[#395B64]" />
                  {fup.workerName}
                </span>
                <span>•</span>
                <span>{new Date(fup.interventionDate).toLocaleDateString()}</span>
              </div>
            </div>

            {/* Indicator Comparison Cards */}
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
              <div className="p-3.5 rounded-2xl bg-[#F9FBFA] border border-[#E7EDEA]">
                <span className="text-[10px] font-bold text-[#7F8C8D] uppercase block mb-0.5">
                  Original Indicator
                </span>
                <div className="flex items-baseline space-x-1">
                  <span className="text-2xl font-black text-[#2C3639]">{fup.originalScore}</span>
                  <span className="text-xs text-[#7F8C8D]">/100</span>
                </div>
              </div>

              <div className="p-3.5 rounded-2xl bg-[#F9FBFA] border border-[#E7EDEA]">
                <span className="text-[10px] font-bold text-[#7F8C8D] uppercase block mb-0.5">
                  Follow-up Indicator
                </span>
                <div className="flex items-baseline space-x-1">
                  <span className="text-2xl font-black text-[#2C3639]">
                    {fup.followUpScore !== undefined ? fup.followUpScore : "—"}
                  </span>
                  {fup.followUpScore !== undefined && <span className="text-xs text-[#7F8C8D]">/100</span>}
                </div>
              </div>

              <div className="p-3.5 rounded-2xl bg-[#F9FBFA] border border-[#E7EDEA]">
                <span className="text-[10px] font-bold text-[#7F8C8D] uppercase block mb-0.5">
                  Indicator Change (Δ)
                </span>
                <div className="flex items-center space-x-1.5">
                  {fup.scoreDelta !== undefined ? (
                    <>
                      {fup.scoreDelta < 0 ? (
                        <TrendingDown size={20} className="text-emerald-600" />
                      ) : fup.scoreDelta > 0 ? (
                        <TrendingUp size={20} className="text-[#D68060]" />
                      ) : (
                        <Minus size={20} className="text-[#7F8C8D]" />
                      )}
                      <span className={`text-2xl font-black ${
                        fup.scoreDelta < 0 ? "text-emerald-600" : fup.scoreDelta > 0 ? "text-[#D68060]" : "text-[#2C3639]"
                      }`}>
                        {fup.scoreDelta > 0 ? `+${fup.scoreDelta}` : fup.scoreDelta} pts
                      </span>
                    </>
                  ) : (
                    <span className="text-xs text-[#7F8C8D] italic">Pending reflection</span>
                  )}
                </div>
              </div>

              <div className="p-3.5 rounded-2xl bg-[#F9FBFA] border border-[#E7EDEA]">
                <span className="text-[10px] font-bold text-[#7F8C8D] uppercase block mb-0.5">
                  Intervention Format
                </span>
                <p className="text-xs font-bold text-[#2C3639] line-clamp-2">
                  {fup.interventionType}
                </p>
              </div>
            </div>

            {/* Case Worker Clinical Summary */}
            <div className="p-3.5 rounded-2xl bg-[#F9FBFA] border border-[#E7EDEA] text-xs text-[#5A6B6D] flex items-start space-x-2">
              <FileText size={15} className="text-[#395B64] shrink-0 mt-0.5" />
              <p className="leading-relaxed">
                <strong>Worker Notes:</strong> {fup.notes}
              </p>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

