  // Consent states
  const [consentVoluntary, setConsentVoluntary] = useState(true);
  const [consentNoDiag, setConsentNoDiag] = useState(true);

  // Form answers
  const [wellbeing, setWellbeing] = useState<WellbeingScore>(3);
