                  </span>
                </div>
                <p className="text-[#5A6B6D] italic">"{currentReflection?.transcript || freeTextNotes}"</p>
              </div>

              <ReflectionAnalysis
                analysis={currentReflection?.analysis || analyzeReflection(freeTextNotes)}
                isDemoSample={currentReflection?.analysis?.isDemoSample}
              />
            </div>
          )}

          {/* Explainable Factors */}
          <div className="space-y-3">
            <h4 className="text-xs font-black uppercase tracking-wider text-[#7F8C8D]">
              {t.factorsReasoning}
            </h4>
            <div className="space-y-2">
              {resultAnalysis.factors.map((f, i) => (
                <div key={i} className="p-3.5 rounded-2xl bg-[#F9FBFA] border border-[#E7EDEA] text-xs sm:text-sm text-[#2C3639] flex items-start space-x-2.5">
                  <span className="w-1.5 h-1.5 rounded-full bg-[#395B64] shrink-0 mt-2"></span>
                  <span>{f}</span>
                </div>
              ))}
            </div>
          </div>

          {/* Recommended Next Step */}
          <div className="p-5 rounded-2xl bg-[#A5C9CA]/15 border border-[#A5C9CA]/30 space-y-2">
            <h4 className="text-xs font-bold uppercase tracking-wider text-[#395B64]">
              System Recommendation
            </h4>
            <p className="text-sm font-medium text-[#2C3639] leading-relaxed">
              {resultAnalysis.recommendation}
            </p>
          </div>

          {/* Ethical Disclaimer */}
          <div className="text-center p-3 rounded-xl bg-[#F9FBFA] border border-[#E7EDEA] text-[11px] text-[#7F8C8D]">
            <strong className="text-[#2C3639]">Ethical Notice:</strong> {t.ethicalNotice}
          </div>

          {/* Navigation Action */}
          <div className="pt-2 flex flex-col sm:flex-row gap-3">
            <button
              onClick={onGoToProfile}
              className="w-full py-4 rounded-2xl bg-[#2C3639] text-white font-bold text-sm hover:bg-[#3F4E4E] transition-all flex items-center justify-center space-x-2 cursor-pointer"
            >
              <span>View My History & Trends in Profile</span>
              <ArrowRight size={16} />
            </button>
          </div>
        </div>
      </div>
    );
  }

  // Interactive Question Card (Steps 1 - 8)
  return (
    <div className="max-w-2xl mx-auto py-8 px-4 sm:px-6 space-y-6">
      {/* Top Header & Progress */}
      <div className="bg-white rounded-3xl p-6 sm:p-8 border border-[#E7EDEA] shadow-xs space-y-4">
        <div className="flex items-center justify-between text-xs text-[#7F8C8D] font-bold">
          <span>Question {currentQuestionNumber} of {totalQuestions}</span>
          <div className="flex items-center space-x-3">
            {/* Language Selector */}
            <select
              value={lang}
              onChange={(e) => setLang(e.target.value as Language)}
              className="text-xs font-bold text-[#2C3639] bg-[#F9FBFA] border border-[#E7EDEA] rounded-lg px-2 py-1 focus:outline-none cursor-pointer"
            >
              <option value="en">EN</option>
              <option value="hi">HI</option>
              <option value="mr">MR</option>
            </select>
            <button
              onClick={onGoToProfile}
              className="text-[#7F8C8D] hover:text-[#2C3639] transition-colors cursor-pointer"
