      {/* Main Question Body */}
      <div className="bg-white rounded-3xl p-6 sm:p-10 border border-[#E7EDEA] shadow-xs space-y-8 min-h-[380px] flex flex-col justify-between">
        {/* Step 1: Overall Wellbeing */}
        {step === 1 && (
          <div className="space-y-6">
            <div className="space-y-2">
              <span className="text-xs font-black uppercase tracking-wider text-[#395B64]">
