            <div className="grid grid-cols-5 gap-2 sm:gap-3 pt-4">
              {[
                { val: 1, label: t.veryDifficult, icon: <Frown size={24} className="text-[#D68060]" /> },
                { val: 2, label: t.difficult, icon: <Frown size={24} className="text-[#D49B6A]" /> },
