                  key={opt.val}
                  onClick={() => setSafety(opt.val as SafetyResponse)}
                  className={`p-4 rounded-2xl border text-left transition-all flex items-center justify-between cursor-pointer ${
                    safety === opt.val
                      ? "border-[#395B64] bg-[#A5C9CA]/20 shadow-xs ring-2 ring-[#395B64]/30 font-bold"
                      : "border-[#E7EDEA] hover:border-[#A5C9CA] hover:bg-[#F9FBFA] font-medium"
                  }`}
                >
                  <span className="text-sm text-[#2C3639]">{opt.label}</span>
                  {safety === opt.val && <CheckCircle2 size={18} className="text-[#395B64]" />}
                </button>
              ))}
            </div>
          </div>
        )}

        {/* Step 5: Social Connection */}
        {step === 5 && (
          <div className="space-y-6">
            <div className="space-y-2">
              <span className="text-xs font-black uppercase tracking-wider text-[#395B64]">
                Step 5 • Social Connection
              </span>
              <h3 className="text-2xl sm:text-3xl font-black text-[#2C3639]">
                {t.connectedCommunity}
              </h3>
              <p className="text-xs sm:text-sm text-[#7F8C8D]">
                Feelings of isolation or being supported by people around you.
              </p>
            </div>

            <div className="grid grid-cols-5 gap-2 sm:gap-3 pt-4">
              {[
                { val: 1, label: t.isolated },
                { val: 2, label: t.mostlyAlone },
                { val: 3, label: t.someContact },
                { val: 4, label: t.connected },
                { val: 5, label: t.stronglySupported }
              ].map(opt => (
                <button
                  key={opt.val}
                  onClick={() => setConnection(opt.val as WellbeingScore)}
                  className={`p-3 sm:p-4 rounded-2xl border text-center transition-all flex flex-col items-center justify-center space-y-2 cursor-pointer ${
                    connection === opt.val
                      ? "border-[#395B64] bg-[#A5C9CA]/20 shadow-xs ring-2 ring-[#395B64]/30"
                      : "border-[#E7EDEA] hover:border-[#A5C9CA] hover:bg-[#F9FBFA]"
                  }`}
                >
                  <Users size={20} className={connection === opt.val ? "text-[#395B64]" : "text-[#7F8C8D]"} />
                  <span className="text-lg font-black text-[#2C3639]">{opt.val}</span>
                  <span className="text-[10px] font-bold text-[#5A6B6D]">{opt.label}</span>
                </button>
              ))}
            </div>
            <p className="text-center text-xs text-[#7F8C8D]">1 = Very isolated • 5 = Strongly supported</p>
          </div>
        )}

        {/* Step 6: Optional Voice or Free-Text Reflection */}
        {step === 6 && (
          <div className="space-y-6">
            <div className="space-y-2">
              <span className="text-xs font-black uppercase tracking-wider text-[#395B64]">
                Step 6 • Optional Voice / Text Reflection
              </span>
              <h3 className="text-2xl sm:text-3xl font-black text-[#2C3639]">
                Share any additional feelings or thoughts (Optional)
              </h3>
              <p className="text-xs sm:text-sm text-[#7F8C8D]">
                Optional voice reflection can be transcribed and analyzed as an additional wellbeing signal.
              </p>
            </div>

            <VoiceRecorder
              participantId={participantId}
              onSaveReflection={(ref) => {
                setCurrentReflection(ref);
                setFreeTextNotes(ref?.transcript || "");
              }}
              onClearReflection={() => {
                setCurrentReflection(null);
                setFreeTextNotes("");
              }}
              initialTranscript={currentReflection?.transcript || freeTextNotes}
              onSkip={handleNext}
            />
          </div>
        )}

        {/* Step 7: Support Request */}
        {step === 7 && (
          <div className="space-y-6">
            <div className="space-y-2">
              <span className="text-xs font-black uppercase tracking-wider text-[#395B64]">
                Step 7 • Counselor Connection
              </span>
              <h3 className="text-2xl sm:text-3xl font-black text-[#2C3639]">
                {t.supportPersonCheckin}
              </h3>
              <p className="text-xs sm:text-sm text-[#7F8C8D]">
                Checking yes will notify our humanitarian support team for a voluntary follow-up.
              </p>
            </div>

            <div className="grid sm:grid-cols-2 gap-4 pt-2">
              <button
                onClick={() => setSupportRequested(true)}
                className={`p-5 rounded-2xl border text-left transition-all cursor-pointer ${
                  supportRequested === true
                    ? "border-[#395B64] bg-[#A5C9CA]/20 shadow-xs ring-2 ring-[#395B64]/30"
                    : "border-[#E7EDEA] hover:bg-[#F9FBFA]"
                }`}
              >
                <div className="flex items-center justify-between mb-2">
                  <span className="font-bold text-[#2C3639]">{t.yesConnect}</span>
                  {supportRequested === true && <CheckCircle2 size={18} className="text-[#395B64]" />}
                </div>
                <p className="text-xs text-[#7F8C8D]">
                  A support worker will arrange a voluntary, confidential conversation.
                </p>
              </button>

              <button
                onClick={() => setSupportRequested(false)}
                className={`p-5 rounded-2xl border text-left transition-all cursor-pointer ${
                  supportRequested === false
                    ? "border-[#395B64] bg-[#A5C9CA]/20 shadow-xs ring-2 ring-[#395B64]/30"
                    : "border-[#E7EDEA] hover:bg-[#F9FBFA]"
                }`}
              >
                <div className="flex items-center justify-between mb-2">
                  <span className="font-bold text-[#2C3639]">{t.noTracking}</span>
                  {supportRequested === false && <CheckCircle2 size={18} className="text-[#395B64]" />}
                </div>
                <p className="text-xs text-[#7F8C8D]">
                  Continue your regular self-reflection without scheduling a call.
                </p>
              </button>
            </div>
          </div>
        )}

        {/* Step 8: Immediate Safety Screen */}
        {step === 8 && (
          <div className="space-y-6">
            <div className="space-y-2">
              <span className="text-xs font-black uppercase tracking-wider text-[#D68060]">
                Step 8 • Immediate Safety Confirmation
              </span>
              <h3 className="text-2xl sm:text-3xl font-black text-[#2C3639]">
                Are you in immediate physical danger or thinking of hurting yourself?
              </h3>
              <p className="text-xs sm:text-sm text-[#7F8C8D]">
                This helps us provide immediate emergency resources if you are in danger right now.
              </p>
            </div>

            <div className="space-y-3 pt-2">
              <button
                onClick={() => {
                  setImmediateSafetyConcern(false);
                  handleNext();
                }}
                className="w-full p-4 rounded-2xl border-2 border-[#E7EDEA] hover:border-[#395B64] hover:bg-[#A5C9CA]/15 transition-all text-left flex items-center justify-between cursor-pointer"
              >
                <div>
                  <span className="font-bold text-[#2C3639] block text-sm">
                    No, I am safe right now.
                  </span>
                  <span className="text-xs text-[#7F8C8D]">
                    Complete check-in and view your reflection trends.
                  </span>
                </div>
                <CheckCircle2 size={20} className="text-[#7F8C8D]" />
              </button>

              <button
                onClick={handleEmergencyTrigger}
                className="w-full p-4 rounded-2xl border-2 border-[#D68060]/40 bg-[#D68060]/10 hover:bg-[#D68060]/20 transition-all text-left flex items-center justify-between cursor-pointer"
              >
                <div>
                  <span className="font-bold text-[#D68060] block text-sm">
                    Yes, I need immediate emergency help or support.
                  </span>
                  <span className="text-xs text-[#D68060]/90">
                    Access crisis hotlines and humanitarian alert protocol immediately.
                  </span>
                </div>
                <AlertTriangle size={20} className="text-[#D68060]" />
              </button>
            </div>
          </div>
        )}

        {/* Footer controls: Back, Skip, Next */}
        <div className="pt-6 border-t border-[#E7EDEA] flex items-center justify-between">
          <button
            onClick={() => setStep(Math.max(1, step - 1))}
            disabled={step <= 1}
            className="text-xs font-bold text-[#7F8C8D] hover:text-[#2C3639] disabled:opacity-30 disabled:cursor-not-allowed flex items-center space-x-1 cursor-pointer"
          >
            <ArrowLeft size={14} />
            <span>{t.previous}</span>
          </button>

          <div className="flex items-center space-x-3">
            {step < 8 && (
              <button
                onClick={handleNext}
                className="text-xs font-semibold text-[#7F8C8D] hover:text-[#2C3639] underline cursor-pointer"
              >
                {t.skip}
              </button>
            )}

            {step < 8 ? (
              <button
                onClick={handleNext}
                className="px-6 py-3 rounded-xl bg-[#2C3639] text-white font-bold text-sm hover:bg-[#3F4E4E] transition-all shadow-xs flex items-center space-x-2 active:scale-95 cursor-pointer"
              >
                <span>{t.continue}</span>
                <ArrowRight size={16} />
              </button>
            ) : (
              <button
                onClick={handleNext}
                className="px-6 py-3 rounded-xl bg-[#2C3639] text-white font-bold text-sm hover:bg-[#3F4E4E] transition-all shadow-xs flex items-center space-x-2 active:scale-95 cursor-pointer"
              >
                <span>{t.submitCheckin}</span>
                <CheckCircle2 size={16} />
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from "react";
import {
  ArrowLeft,
  Shield,
  Activity,
  Calendar,
  Clock,
  HeartHandshake,
  TrendingUp,
  TrendingDown,
  AlertTriangle,
  CheckCircle2,
  Send,
  MessageSquare,
  User,
  ExternalLink,
  LifeBuoy,
  Sparkles,
  UserCheck
} from "lucide-react";
import {
  ResponsiveContainer,
  AreaChart,
  Area,
  XAxis,
  YAxis,
  Tooltip,
  CartesianGrid
} from "recharts";
import { Participant, SupportNote } from "../types";
import { analyzeDistress } from "../services/riskEngine";
import { analyzeParticipantTrajectory, generateEarlyWarningForecast } from "../services/trajectoryEngine";
import { generateSupportRecommendation } from "../services/supportRecommendationEngine";
import { ExplainableAISignal } from "../components/ExplainableAISignal";
import { EarlyWarningForecastCard } from "../components/EarlyWarningForecastCard";
import { SuggestedSupportPlanCard } from "../components/SuggestedSupportPlanCard";
import { InterventionTimeline } from "../components/InterventionTimeline";
import { SignalStrengthVsHumanCard } from "../components/ResponsibleAIBadges";

interface Props {
  participant: Participant;
  onBack: () => void;
  onUpdateStatus: (participantId: string, newStatus: any) => void;
  onAddNote: (participantId: string, note: SupportNote) => void;
  onOpenEmergency: () => void;
  onAssignWorker?: (participantId: string, workerName: string) => void;
}

export const ParticipantDetail: React.FC<Props> = ({
  participant,
  onBack,
  onUpdateStatus,
  onAddNote,
  onOpenEmergency,
  onAssignWorker
}) => {
  const [newNoteText, setNewNoteText] = useState("");
  const [actionCategory, setActionCategory] = useState("Voluntary counseling call");
  const [selectedDecision, setSelectedDecision] = useState(participant.status);

  const checkIns = participant?.checkIns || [];
  const latestCheckIn = checkIns.length > 0 ? checkIns[checkIns.length - 1] : null;
  const previousCheckIn = checkIns.length > 1 ? checkIns[checkIns.length - 2] : null;

  // Run explainable analysis & dynamic trajectory engine
  const riskAnalysis = latestCheckIn ? analyzeDistress(latestCheckIn, previousCheckIn) : null;
  const trajectory = analyzeParticipantTrajectory(participant);
  const forecast = generateEarlyWarningForecast(participant?.checkIns || [], trajectory);
  const supportPlan = generateSupportRecommendation(latestCheckIn, trajectory);

  // Prepare chart data
  const trendData = checkIns.map((c, idx) => ({
    day: `Check-in ${idx + 1}`,
    score: c.calculatedScore || 0,
    stress: c.stress * 20,
    sleep: c.sleep * 20,
    date: new Date(c.timestamp).toLocaleDateString(undefined, { month: "short", day: "numeric" })
  }));

  const handleAddNote = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newNoteText.trim()) return;

    const note: SupportNote = {
      id: `n-${Date.now()}-${Math.random().toString(36).substring(2, 7)}`,
      author: "Dr. Sarah Jenkins, MSW",
      timestamp: new Date().toISOString(),
      text: newNoteText.trim(),
      actionTaken: actionCategory
    };

    onAddNote(participant.id, note);
    setNewNoteText("");
  };

  const handleStatusChange = (newStatus: any) => {
    setSelectedDecision(newStatus);
    onUpdateStatus(participant.id, newStatus);
  };

  const isUrgent = participant.status === "Urgent safety signal" || riskAnalysis?.level === "Urgent";

  return (
    <div className="max-w-7xl mx-auto py-8 px-4 sm:px-6 lg:px-8 space-y-8">
      {/* Top Breadcrumb & Actions */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <button
          onClick={onBack}
          className="text-xs font-bold text-[#7F8C8D] hover:text-[#2C3639] transition-colors flex items-center space-x-1.5 self-start cursor-pointer"
        >
          <ArrowLeft size={14} />
          <span>Back to Case Hub</span>
        </button>

        <div className="flex items-center space-x-3">
          {isUrgent && (
            <button
              onClick={onOpenEmergency}
              className="px-4 py-2 rounded-xl bg-[#D68060] text-white text-xs font-bold hover:bg-[#D68060]/90 transition-colors flex items-center space-x-1.5 shadow-xs cursor-pointer"
            >
              <LifeBuoy size={14} />
              <span>Emergency Protocols</span>
            </button>
          )}
          <span className="text-xs font-mono font-bold text-[#7F8C8D]">
            Case ID: {participant.id}
          </span>
        </div>
      </div>

      {/* Participant Header Card */}
      <div className="bg-white rounded-3xl p-6 sm:p-8 border border-[#E7EDEA] shadow-xs flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div className="space-y-2">
          <div className="flex flex-wrap items-center gap-2">
            <span className="font-mono text-2xl font-black text-[#2C3639]">{participant.id}</span>
            <span className={`text-xs font-bold px-3 py-1 rounded-xl ${
              isUrgent ? "bg-[#D68060]/15 text-[#D68060] border border-[#D68060]/30" :
              participant.status === "Needs follow-up" ? "bg-[#D49B6A]/15 text-[#D49B6A] border border-[#D49B6A]/30" :
              participant.status === "Improving" ? "bg-[#A5C9CA]/25 text-[#395B64]" :
              "bg-[#E7EDEA] text-[#5A6B6D]"
            }`}>
              {participant.status}
            </span>

            {/* Trajectory classification badge */}
            <span className="text-xs font-bold px-3 py-1 rounded-xl bg-[#395B64]/10 text-[#395B64] border border-[#395B64]/20 flex items-center space-x-1">
              <span>Trajectory: {trajectory.classification}</span>
            </span>
          </div>

          <div className="flex flex-wrap items-center gap-4 text-xs text-[#7F8C8D] pt-1">
            <span>Language: <strong className="text-[#2C3639]">{participant.language}</strong></span>
            <span>Age Group: <strong className="text-[#2C3639]">{participant.ageGroup}</strong></span>
            <span>Support Preference: <strong className="text-[#2C3639]">{participant.preferredSupport}</strong></span>
            <span>Assigned: <strong className="text-[#2C3639]">{participant.assignedWorker || "Unassigned"}</strong></span>
          </div>
        </div>

        {/* Score & Change Stats */}
        <div className="flex items-center space-x-4 border-t md:border-t-0 md:border-l pt-4 md:pt-0 md:pl-8 border-[#E7EDEA] shrink-0">
          <div>
            <span className="text-[11px] font-bold uppercase tracking-wider text-[#7F8C8D] block">
              Current Distress Indicator
            </span>
            {checkIns.length === 0 ? (
              <div className="text-xl font-black text-[#7F8C8D]">
                Not assessed
              </div>
            ) : (
              <div className="text-3xl font-black text-[#2C3639]">
                {trajectory.currentScore || (riskAnalysis?.score ?? 0)}
                <span className="text-sm font-semibold text-[#7F8C8D]">/100</span>
              </div>
            )}
          </div>

          <div className={`p-3 rounded-2xl ${
            checkIns.length === 0
              ? "bg-[#F9FBFA] text-[#7F8C8D] border border-[#E7EDEA]"
              : riskAnalysis && riskAnalysis.change > 0
              ? "bg-[#D68060]/15 text-[#D68060] border border-[#D68060]/30"
              : riskAnalysis && riskAnalysis.change < 0
              ? "bg-[#A5C9CA]/20 text-[#395B64] border border-[#A5C9CA]/40"
              : "bg-[#F9FBFA] text-[#7F8C8D] border border-[#E7EDEA]"
          }`}>
            <div className="text-xs font-bold flex items-center">
              {checkIns.length === 0 ? (
                <span>Awaiting Check-in</span>
              ) : checkIns.length === 1 ? (
                <span>Baseline (1st entry)</span>
              ) : riskAnalysis && riskAnalysis.change > 0 ? (
                <>
                  <TrendingUp size={14} className="mr-1" /> +{riskAnalysis.change} pts
                </>
              ) : riskAnalysis && riskAnalysis.change < 0 ? (
                <>
                  <TrendingDown size={14} className="mr-1" /> {riskAnalysis.change} pts
                </>
              ) : (
                <span>0 pts (Stable)</span>
              )}
            </div>
            <span className="text-[10px] block opacity-80 mt-0.5">Rate of Change</span>
          </div>
        </div>
      </div>

      {/* Signal Strength vs Human Review Mandate */}
      <SignalStrengthVsHumanCard
        signalText={trajectory.summaryDescription}
        score={trajectory.currentScore}
      />

      {/* Suggested Support Plan Card (Requirement #5) */}
      <SuggestedSupportPlanCard
        plan={supportPlan}
        participant={participant}
        participantId={participant?.id}
        onAssignWorker={onAssignWorker}
        onScheduleFollowUp={(pId, date, reason) => {
          const note: SupportNote = {
            id: `n-${Date.now()}`,
            author: "Dr. Sarah Jenkins, MSW",
            timestamp: new Date().toISOString(),
            text: `Scheduled proactive follow-up for ${date}: ${reason}`,
            actionTaken: "Scheduled Follow-up"
          };
          onAddNote(pId, note);
        }}
      />

      {/* Main Analysis Grid */}
      <div className="grid lg:grid-cols-12 gap-8">
        {/* Left 7 Cols: Trajectory Graph + Explainable Factor Breakdown + Early Warning */}
        <div className="lg:col-span-7 space-y-8">
          {/* Trend Chart */}
          <div className="bg-white p-6 sm:p-8 rounded-3xl border border-[#E7EDEA] shadow-xs space-y-4">
            <div className="flex items-center justify-between">
              <div>
                <h3 className="text-lg font-bold text-[#2C3639]">Multi-Check-in Trend Trajectory</h3>
                <p className="text-xs text-[#7F8C8D]">Dynamic score calculation across consecutive voluntary reflections</p>
              </div>
              <span className="text-xs font-bold text-[#395B64] bg-[#A5C9CA]/20 px-2.5 py-1 rounded-lg">
                {checkIns.length} Entries
              </span>
            </div>

            {checkIns.length === 0 ? (
              <div className="py-12 px-6 rounded-2xl bg-[#F9FBFA] border border-dashed border-[#A5C9CA] text-center space-y-2">
                <span className="text-xs font-bold text-[#395B64] uppercase tracking-wider block">
                  No Reflections Logged
                </span>
                <p className="text-sm font-bold text-[#2C3639]">
                  Participant has not submitted any check-ins yet.
                </p>
                <p className="text-xs text-[#7F8C8D] max-w-sm mx-auto">
                  Distress indicator signals and trend trajectories will appear here once reflections are recorded.
                </p>
              </div>
            ) : (
              <div className="h-60 w-full pt-2">
                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={trendData} margin={{ top: 10, right: 10, left: -20, bottom: 0 }}>
                    <defs>
                      <linearGradient id="detailGradient" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor="#395B64" stopOpacity={0.3} />
                        <stop offset="95%" stopColor="#395B64" stopOpacity={0.0} />
                      </linearGradient>
                    </defs>
                    <CartesianGrid strokeDasharray="3 3" stroke="#E7EDEA" vertical={false} />
                    <XAxis dataKey="date" stroke="#7F8C8D" fontSize={11} tickLine={false} />
                    <YAxis domain={[0, 100]} stroke="#7F8C8D" fontSize={11} tickLine={false} />
                    <Tooltip
                      contentStyle={{ backgroundColor: "#2C3639", border: "1px solid #3F4E4E", borderRadius: "1rem", color: "#fff", fontSize: "12px" }}
                      formatter={(val: number) => [`${val}/100`, "Distress Indicator"]}
                    />
                    <Area
                      type="monotone"
                      dataKey="score"
                      stroke="#395B64"
                      strokeWidth={3}
                      fillOpacity={1}
                      fill="url(#detailGradient)"
                    />
                  </AreaChart>
                </ResponsiveContainer>
              </div>
            )}
          </div>

          {/* Explainable AI (XAI) Signal Component (Requirement #4) */}
          <ExplainableAISignal
            factors={supportPlan?.contributingFactors}
            overallConfidence="High (92%)"
            summaryStatement={trajectory?.summaryDescription}
          />

          {/* Early-Warning Forecast Card (Requirement #3) */}
          <EarlyWarningForecastCard
            forecast={forecast}
            trajectory={trajectory}
            participantId={participant.id}
          />
        </div>

        {/* Right 5 Cols: Timeline & Human-in-the-Loop Case Management */}
        <div className="lg:col-span-5 space-y-8">
          {/* Support and Outcome Timeline (Requirement #7) */}
          <InterventionTimeline
            participant={participant}
            trajectory={trajectory}
          />

          {/* Human Review Decision & Status Control */}
          <div className="bg-white p-6 sm:p-8 rounded-3xl border border-[#E7EDEA] shadow-xs space-y-6">
            <h3 className="text-base font-bold text-[#2C3639]">Human Review & Escalation</h3>

            <div className="space-y-2">
              <label className="block text-xs font-bold text-[#7F8C8D] uppercase tracking-wider">
                Case Disposition Status
              </label>
              <select
                value={selectedDecision}
                onChange={(e) => handleStatusChange(e.target.value)}
                className="w-full p-3 rounded-xl border border-[#E7EDEA] bg-[#F9FBFA] text-xs font-bold text-[#2C3639] focus:ring-2 focus:ring-[#395B64] focus:outline-none cursor-pointer"
              >
                <option value="Needs follow-up">Needs follow-up (Schedule Outreach)</option>
                <option value="Human review pending">Human review pending</option>
                <option value="Urgent safety signal">Urgent safety signal (Emergency Protocol)</option>
                <option value="Improving">Improving (Continue Observation)</option>
                <option value="Stable">Stable (Routine Monitoring)</option>
              </select>
            </div>

            {/* Notes Log */}
            <div className="space-y-3 pt-2 border-t border-[#E7EDEA]">
              <h4 className="text-xs font-bold uppercase tracking-wider text-[#7F8C8D] flex items-center justify-between">
                <span>Support Case Notes ({(participant?.notes || []).length})</span>
                <MessageSquare size={13} />
              </h4>

              <div className="space-y-2.5 max-h-48 overflow-y-auto">
                {(participant?.notes || []).length > 0 ? (
                  (participant.notes || []).map((n) => (
                    <div key={n.id} className="p-3 rounded-2xl bg-[#F9FBFA] border border-[#E7EDEA] text-xs space-y-1">
                      <div className="flex items-center justify-between text-[10px] text-[#7F8C8D] font-bold">
                        <span>{n.author}</span>
                        <span>{new Date(n.timestamp).toLocaleDateString()}</span>
                      </div>
                      <p className="text-[#2C3639] font-medium">{n.text}</p>
                      {n.actionTaken && (
                        <span className="inline-block text-[10px] font-bold text-[#395B64] bg-[#A5C9CA]/20 px-2 py-0.5 rounded-md">
                          Action: {n.actionTaken}
                        </span>
                      )}
                    </div>
                  ))
                ) : (
                  <p className="text-xs text-[#7F8C8D] italic">No notes recorded yet for this participant.</p>
                )}
              </div>

              {/* Add Note Form */}
              <form onSubmit={handleAddNote} className="space-y-2 pt-2">
                <textarea
                  rows={2}
                  placeholder="Record counseling conversation notes or actions..."
                  value={newNoteText}
                  onChange={(e) => setNewNoteText(e.target.value)}
                  className="w-full p-3 rounded-xl border border-[#E7EDEA] bg-[#F9FBFA] text-xs text-[#2C3639] focus:ring-2 focus:ring-[#395B64] focus:outline-none"
                />
                <div className="flex items-center justify-between gap-2">
                  <select
                    value={actionCategory}
                    onChange={(e) => setActionCategory(e.target.value)}
                    className="p-2 rounded-xl border border-[#E7EDEA] bg-[#F9FBFA] text-[11px] font-medium text-[#2C3639] cursor-pointer"
                  >
                    <option value="Voluntary counseling call">Voluntary counseling call</option>
                    <option value="In-person check-in">In-person check-in</option>
                    <option value="Grounding exercise provided">Grounding exercise provided</option>
                    <option value="Peer group referral">Peer group referral</option>
                  </select>
                  <button
                    type="submit"
                    className="px-4 py-2 rounded-xl bg-[#2C3639] text-white text-xs font-bold hover:bg-[#3F4E4E] transition-colors flex items-center space-x-1 cursor-pointer"
                  >
                    <Send size={12} />
                    <span>Add Note</span>
                  </button>
                </div>
              </form>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo } from "react";
import {
  Users,
  AlertTriangle,
  TrendingUp,
  TrendingDown,
  CheckCircle2,
  Search,
  Filter,
  ArrowRight,
  Shield,
  Clock,
  Sparkles,
  Activity,
  UserCheck,
  ChevronRight,
  HelpCircle,
  Eye,
  HeartHandshake,
  Bell,
  ArrowUpRight,
  Info
} from "lucide-react";
import {
  ResponsiveContainer,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  Tooltip,
  CartesianGrid,
  Cell
} from "recharts";
import { Participant, Alert, DemoScenario, AppNotification } from "../types";
import { ALERT_CONFIG } from "../services/alertConfig";

interface Props {
  participants: Participant[];
  alerts: Alert[];
  onSelectParticipant: (participantId: string) => void;
  onOpenSimulation: () => void;
  onNavigateAlerts: () => void;
  onNavigateNotifications?: () => void;
}

export const SupportDashboard: React.FC<Props> = ({
  participants,
  alerts,
  onSelectParticipant,
  onOpenSimulation,
  onNavigateAlerts,
  onNavigateNotifications
}) => {
  const [searchQuery, setSearchQuery] = useState("");
  const [statusFilter, setStatusFilter] = useState("All");
  const [sortBy, setSortBy] = useState<"score_desc" | "score_asc" | "change_desc" | "recent">("score_desc");

  // Summary Metrics calculations
  const totalCount = participants.length;

  // Prioritized review counts
  const priorityReviewCount = alerts.filter(a => a.severity === "urgent" || a.category === "SAFETY_CONCERN").length;
  const humanReviewCount = alerts.filter(a => (a.severity === "elevated" || a.category === "HIGH" || a.category === "PERSISTENT_INCREASE") && a.status === "pending_review").length;
  const monitoringCount = alerts.filter(a => a.category === "SUPPORT_REQUEST" || a.status === "monitoring" || a.severity === "moderate").length;
  const positiveChangeCount = participants.filter(p => p.status === "Improving").length;

  // Chart data 1: Priority breakdown with Natural Tones palette
  const priorityData = [
    { name: "Priority Review", count: priorityReviewCount, color: "#D68060" },
    { name: "Human Review", count: humanReviewCount, color: "#D49B6A" },
    { name: "Monitoring", count: monitoringCount, color: "#7F8C8D" },
    { name: "Positive Change", count: positiveChangeCount, color: "#395B64" }
  ];

  // Chart data 2: Common flagged factors across all check-ins
  const factorDistribution = useMemo(() => {
    let sleepFlags = 0;
    let stressFlags = 0;
    let safetyFlags = 0;
    let connectionFlags = 0;
    let supportRequests = 0;

    participants.forEach(p => {
      const checkIns = p.checkIns || [];
      const latest = checkIns.length > 0 ? checkIns[checkIns.length - 1] : null;
      if (latest) {
        if (latest.sleep <= 2) sleepFlags++;
        if (latest.stress >= 4) stressFlags++;
        if (latest.safety === "No" || latest.safety === "Unsure") safetyFlags++;
        if (latest.connection <= 2) connectionFlags++;
        if (latest.supportRequested) supportRequests++;
      }
    });

    return [
      { factor: "High Stress (4-5)", count: stressFlags, color: "#D49B6A" },
      { factor: "Sleep Disturbance", count: sleepFlags, color: "#395B64" },
      { factor: "Safety Uncertainty", count: safetyFlags, color: "#D68060" },
      { factor: "Social Isolation", count: connectionFlags, color: "#7F8C8D" },
      { factor: "Voluntary Request", count: supportRequests, color: "#A5C9CA" }
    ];
  }, [participants]);

  // Priority Review queue: Filter active alerts that require review
  const priorityQueue = useMemo(() => {
    return alerts
      .filter(a => a.status === "pending_review" || a.status === "escalated" || a.status === "NEW" || a.status === "IN_REVIEW" || a.status === "SAFETY_ESCALATED")
      .slice(0, 5);
  }, [alerts]);

  // Filtered & Sorted participants
  const filteredParticipants = useMemo(() => {
    return participants
      .filter(p => {
        const matchesSearch = p.id.toLowerCase().includes(searchQuery.toLowerCase()) ||
          (p.assignedWorker && p.assignedWorker.toLowerCase().includes(searchQuery.toLowerCase())) ||
          p.language.toLowerCase().includes(searchQuery.toLowerCase());

        const matchesStatus = statusFilter === "All" || p.status === statusFilter;

        return matchesSearch && matchesStatus;
      })
      .sort((a, b) => {
        const checkInsA = a.checkIns || [];
        const checkInsB = b.checkIns || [];
        const latestA = checkInsA.length > 0 ? (checkInsA[checkInsA.length - 1]?.calculatedScore || 0) : 0;
        const latestB = checkInsB.length > 0 ? (checkInsB[checkInsB.length - 1]?.calculatedScore || 0) : 0;

        const prevA = checkInsA.length > 1 ? (checkInsA[checkInsA.length - 2]?.calculatedScore || latestA) : latestA;
        const prevB = checkInsB.length > 1 ? (checkInsB[checkInsB.length - 2]?.calculatedScore || latestB) : latestB;

        const deltaA = latestA - prevA;
        const deltaB = latestB - prevB;

        if (sortBy === "score_desc") return latestB - latestA;
        if (sortBy === "score_asc") return latestA - latestB;
        if (sortBy === "change_desc") return deltaB - deltaA;
        return 0;
      });
  }, [participants, searchQuery, statusFilter, sortBy]);

  return (
    <div className="max-w-7xl mx-auto py-8 px-4 sm:px-6 lg:px-8 space-y-8">
