export const participantStore = {
  // Initialize storage versioning and trigger backend sync
  init: () => {
    try {
      const ver = localStorage.getItem(STORAGE_VER_KEY);
      if (ver !== CURRENT_VERSION) {
        const existingParticipants = localStorage.getItem(PARTICIPANTS_KEY);
        if (!existingParticipants) {
          localStorage.setItem(PARTICIPANTS_KEY, JSON.stringify(MOCK_PARTICIPANTS));
        }
        const existingAlerts = localStorage.getItem(ALERTS_KEY);
        if (!existingAlerts) {
          localStorage.setItem(ALERTS_KEY, JSON.stringify(INITIAL_ALERTS));
        }
        // Seed default demo notifications for demo workers
        notificationService.seedDemoNotifications();
        localStorage.setItem(STORAGE_VER_KEY, CURRENT_VERSION);
      }
    } catch (e) {
      console.warn("Storage init warning:", e);
    }
    // Asynchronously synchronize with FastAPI PostgreSQL backend
    participantStore.syncWithBackend().catch((err) => {
      console.warn("[ParticipantStore] Async backend sync notice:", err);
    });
  },

  syncWithBackend: async (): Promise<void> => {
    try {
      const backendParticipants = await apiService.participants.getAll();
      if (Array.isArray(backendParticipants) && backendParticipants.length > 0) {
        const mapped: Participant[] = backendParticipants.map((bp: any) => ({
          id: bp.id,
          consentGiven: bp.consent_given ?? true,
          status: bp.status || "Stable",
          preferredSupport: bp.preferred_support || "Human support worker",
          language: bp.language || "English",
          ageGroup: bp.age_group || "25-34",
          assignedWorker: bp.assigned_worker,
          lastReviewDate: bp.last_review_date,
          createdAt: bp.created_at || new Date().toISOString(),
          notes: (bp.notes || []).map((n: any) => ({
            id: n.id,
            participantId: n.participant_id,
            author: n.author,
            timestamp: n.timestamp,
            text: n.text,
            actionTaken: n.action_taken
          })),
          checkIns: (bp.check_ins || []).map((c: any) => ({
            id: c.id,
            participantId: c.participant_id,
            timestamp: c.timestamp,
            wellbeing: c.wellbeing,
            stress: c.stress,
            sleep: c.sleep,
            safety: c.safety,
            connection: c.connection,
            supportRequested: c.support_requested,
            immediateSafetyConcern: c.immediate_safety_concern,
            calculatedScore: c.calculated_score,
            notes: c.notes,
            optionalNote: c.optional_note,
            shareNoteWithWorker: c.share_note_with_worker,
            voiceInputUsed: c.voice_input_used
          }))
        }));
        saveStoredParticipants(mapped);
      }

      const backendAlerts = await apiService.alerts.getAll();
      if (Array.isArray(backendAlerts) && backendAlerts.length > 0) {
        const mappedAlerts: Alert[] = backendAlerts.map((a: any) => ({
          id: a.id,
          participantId: a.participant_id,
          category: a.category,
          severity: a.severity,
          title: a.title,
          reason: a.reason,
          description: a.description,
          recommendedAction: a.recommended_action,
          status: a.status,
          score: a.score,
          changeDelta: a.change_delta,
          assignedTo: a.assigned_to,
          humanDecision: a.human_decision,
          decisionNotes: a.decision_notes,
          actionTaken: a.action_taken,
          reviewedBy: a.reviewed_by,
          reviewedAt: a.reviewed_at,
          contributingFactors: a.contributing_factors,
          trajectory: a.trajectory,
          requiresHumanReview: a.requires_human_review,
          timestamp: a.created_at,
          createdAt: a.created_at
        }));
        saveStoredAlerts(mappedAlerts);
      }
    } catch (err) {
      console.warn("[ParticipantStore] syncWithBackend error or offline:", err);
    }
  },

  getAllParticipants: (): Participant[] => {
    return getStoredParticipants();
  },

  getParticipantById: (participantId: string): Participant | null => {
    const participants = getStoredParticipants();
    return participants.find((p) => p.id === participantId) || null;
  },

  getParticipantForUser: (user: User): Participant => {
    const participants = getStoredParticipants();
    const existing = participants.find((p) => p.id === user.id);

    if (existing) {
      return existing;
    }

    // Special check for demo participant email
    if (user.email === "demo.participant@aura.demo") {
      const demoP = participants.find((p) => p.id === "P-1042");
      if (demoP) return demoP;
    }

    // New user without a participant record - create a fresh record with NO fake historical data
    const newParticipant: Participant = {
      id: user.id,
      consentGiven: user.consentGiven ?? true,
      createdAt: user.createdAt || new Date().toISOString(),
      preferredSupport: user.supportPreference || "In-app support information",
      language: user.language || "English",
      ageGroup: user.ageRange || "25-34",
      status: "Stable",
      notes: [],
      checkIns: []
    };

    const updated = [newParticipant, ...participants];
    saveStoredParticipants(updated);
    return newParticipant;
  },

  registerNewParticipant: (user: User): Participant => {
    const participants = getStoredParticipants();
    const existingIdx = participants.findIndex((p) => p.id === user.id);

    const newParticipant: Participant = {
      id: user.id,
      consentGiven: user.consentGiven ?? true,
      createdAt: user.createdAt || new Date().toISOString(),
      preferredSupport: user.supportPreference || "In-app support information",
      language: user.language || "English",
      ageGroup: user.ageRange || "25-34",
      status: "Stable",
      notes: [],
      checkIns: []
    };

    let updated: Participant[];
    if (existingIdx >= 0) {
      updated = [...participants];
      updated[existingIdx] = newParticipant;
    } else {
      updated = [newParticipant, ...participants];
    }

    saveStoredParticipants(updated);
    return newParticipant;
  },

  /**
   * CENTRAL CHECK-IN EVALUATION & NOTIFICATION PIPELINE
   */
  saveCheckIn: (checkIn: CheckIn): { participant: Participant; alert?: Alert; decision: AlertDecision; analysis: CheckInAnalysis } => {
    const participants = getStoredParticipants();
    const participantIndex = participants.findIndex((p) => p.id === checkIn.participantId);

    const existingCheckIns = participantIndex >= 0 ? participants[participantIndex].checkIns : [];
    const previousCheckIn = existingCheckIns.length > 0 ? existingCheckIns[existingCheckIns.length - 1] : null;

    // Run dynamic analysis and recommendation calculation
    const analysis = calculateCheckInAnalysis(checkIn, previousCheckIn, existingCheckIns);

    const enrichedCheckIn: CheckIn = {
      ...checkIn,
      calculatedScore: analysis.distressScore,
      analysis: analysis
    };

    let targetParticipant: Participant;

    if (participantIndex >= 0) {
      targetParticipant = {
        ...participants[participantIndex],
        checkIns: [...participants[participantIndex].checkIns, enrichedCheckIn]
      };
    } else {
      targetParticipant = {
        id: checkIn.participantId,
        consentGiven: true,
        createdAt: new Date().toISOString(),
        preferredSupport: "In-app support information",
        language: "English",
        ageGroup: "25-34",
        status: "Stable",
        notes: [],
        checkIns: [enrichedCheckIn]
      };
    }

    // RUN CENTRAL ALERT ENGINE
    const currentAlerts = getStoredAlerts();
    const decision = evaluateCheckIn(enrichedCheckIn, targetParticipant.checkIns, currentAlerts);

    // Update participant status based on alert decision
    if (decision.alert.category === "SAFETY_CONCERN") {
      targetParticipant.status = "Urgent safety signal";
    } else if (decision.alert.category === "PRIORITY" || decision.alert.category === "HIGH" || decision.alert.category === "PERSISTENT_INCREASE") {
      targetParticipant.status = "Human review pending";
    } else if (decision.alert.category === "SUPPORT_REQUEST" || decision.alert.category === "EARLY_WARNING" || decision.alert.category === "ELEVATED") {
      targetParticipant.status = "Needs follow-up";
    } else if (decision.alert.category === "IMPROVEMENT" || decision.alert.category === "RECOVERY") {
      targetParticipant.status = "Improving";
    } else {
      targetParticipant.status = "Stable";
    }

    // Save updated participant
    if (participantIndex >= 0) {
      participants[participantIndex] = targetParticipant;
      saveStoredParticipants(participants);
    } else {
      saveStoredParticipants([targetParticipant, ...participants]);
    }

    // Save or update alert
    let updatedAlerts = [...currentAlerts];
    if (decision.isNewAlert) {
      if (decision.alert.requiresHumanReview || decision.alert.category === "SUPPORT_REQUEST" || decision.alert.category === "SAFETY_CONCERN") {
        updatedAlerts = [decision.alert, ...updatedAlerts];
        saveStoredAlerts(updatedAlerts);
      }
    } else {
      const idx = updatedAlerts.findIndex(a => a.id === decision.alert.id);
      if (idx >= 0) {
        updatedAlerts[idx] = decision.alert;
        saveStoredAlerts(updatedAlerts);
      }
    }

    // 1. RECORD AUDIT: CHECK_IN_SUBMITTED
    auditService.recordAuditEvent({
      actorId: enrichedCheckIn.participantId,
      actorRole: "PARTICIPANT",
      actorName: `Participant ${enrichedCheckIn.participantId}`,
      action: "CHECK_IN_SUBMITTED",
      category: "CHECK_IN",
      participantId: enrichedCheckIn.participantId,
      description: `Participant ${enrichedCheckIn.participantId} submitted a voluntary wellbeing check-in (Stress: ${enrichedCheckIn.stress}/5, Sleep: ${enrichedCheckIn.sleep}/5)`,
      severity: "INFO"
    });

    // 2. RECORD AUDIT: SUPPORT_REQUEST_CREATED (if requested)
    if (enrichedCheckIn.supportRequested) {
      auditService.recordAuditEvent({
        actorId: enrichedCheckIn.participantId,
        actorRole: "PARTICIPANT",
        actorName: `Participant ${enrichedCheckIn.participantId}`,
        action: "SUPPORT_REQUEST_CREATED",
        category: "SUPPORT",
        participantId: enrichedCheckIn.participantId,
        description: `Participant ${enrichedCheckIn.participantId} requested voluntary human support connection`,
        severity: "INFO"
      });
    }

    // 3. RECORD AUDIT: SAFETY_CONCERN_REPORTED (if flagged)
    if (enrichedCheckIn.safety === "No" || enrichedCheckIn.safety === "Unsure" || decision.alert.category === "SAFETY_CONCERN") {
      auditService.recordAuditEvent({
        actorId: enrichedCheckIn.participantId,
        actorRole: "PARTICIPANT",
        actorName: `Participant ${enrichedCheckIn.participantId}`,
        action: "SAFETY_CONCERN_REPORTED",
        category: "SAFETY",
        participantId: enrichedCheckIn.participantId,
        description: `Safety concern reported by participant ${enrichedCheckIn.participantId}`,
        severity: "HIGH"
      });
    }

    // 4. RECORD AUDIT: ANALYSIS_GENERATED
    auditService.recordAuditEvent({
      actorId: "SYSTEM",
      actorRole: "SYSTEM",
      actorName: "AURA AI Signal Engine",
      action: "ANALYSIS_GENERATED",
      category: "ANALYSIS",
      participantId: enrichedCheckIn.participantId,
      description: `AI Signal computed: distress score ${analysis.distressScore}/100 (${decision.alert.trajectory}, change: ${decision.alert.changeDelta >= 0 ? "+" + decision.alert.changeDelta : decision.alert.changeDelta} pts)`,
      severity: analysis.distressScore >= 75 ? "HIGH" : analysis.distressScore >= 50 ? "WARNING" : "INFO"
    });

    // 5. RECORD AUDIT: HIGH_DISTRESS_ALERT_CREATED (if score >= 75 or category HIGH / SAFETY)
    if (analysis.distressScore >= 75 || decision.alert.category === "HIGH" || decision.alert.severity === "urgent") {
      auditService.recordAuditEvent({
        actorId: "SYSTEM",
        actorRole: "SYSTEM",
        actorName: "AURA AI Signal Engine",
        action: "HIGH_DISTRESS_ALERT_CREATED",
        category: "ALERT",
        participantId: enrichedCheckIn.participantId,
        description: `High distress alert created for participant ${enrichedCheckIn.participantId} (Score: ${analysis.distressScore}/100) — routed to Support Worker review queue`,
        severity: "HIGH"
      });
    }

    // DISPATCH NOTIFICATIONS
    // 1. Participant Notification (Calm & non-alarming)
    if (decision.participantNotification) {
      notificationService.createNotification({
        userId: enrichedCheckIn.participantId,
        participantId: enrichedCheckIn.participantId,
        category: decision.participantNotification.category,
        severity: decision.participantNotification.severity,
        title: decision.participantNotification.title,
        message: decision.participantNotification.message,
        actionLabel: decision.alert.category === "SAFETY_CONCERN" ? "View Emergency Help" : "View Wellbeing",
        actionView: decision.alert.category === "SAFETY_CONCERN" ? "emergency" : "participant_home",
        metadata: {
          score: analysis.distressScore,
          change: decision.alert.changeDelta,
          factors: decision.alert.contributingFactors,
          trajectory: decision.alert.trajectory
        }
      });
    }

    // 2. Support Worker Notifications (All active support workers or general worker queue)
    if (decision.workerNotification) {
      const workerQueueIds = ["worker_1", "worker_demo", targetParticipant.assignedWorker || "worker_1"];
      // Deduplicate worker IDs
      const uniqueWorkers = Array.from(new Set(workerQueueIds));
      uniqueWorkers.forEach(wId => {
        notificationService.createNotification({
          userId: wId,
          participantId: enrichedCheckIn.participantId,
          category: decision.workerNotification!.category,
          severity: decision.workerNotification!.severity,
          title: decision.workerNotification!.title,
          message: decision.workerNotification!.message,
          actionLabel: "Review Participant",
          actionView: "detail",
          actionParticipantId: enrichedCheckIn.participantId,
          metadata: {
            score: analysis.distressScore,
            change: decision.alert.changeDelta,
            factors: decision.alert.contributingFactors,
            trajectory: decision.alert.trajectory
          }
        });
      });
    }

    // Persist check-in to FastAPI PostgreSQL backend
    apiService.checkIns.create({
      participantId: checkIn.participantId,
      wellbeing: checkIn.wellbeing,
      stress: checkIn.stress,
      sleep: checkIn.sleep,
      safety: checkIn.safety,
      connection: checkIn.connection,
      supportRequested: checkIn.supportRequested || false,
      immediateSafetyConcern: checkIn.immediateSafetyConcern || false,
      calculatedScore: enrichedCheckIn.calculatedScore,
      notes: checkIn.notes || checkIn.optionalNote,
      optionalNote: checkIn.optionalNote,
      shareNoteWithWorker: checkIn.shareNoteWithWorker ?? true,
      voiceInputUsed: checkIn.voiceInputUsed ?? false
    }).catch((err) => {
      console.warn("[ParticipantStore] CheckIn backend persist notice:", err.message);
    });

    // Persist Risk Prediction to FastAPI backend
    apiService.risk.createPrediction({
      participantId: checkIn.participantId,
      distressScore: enrichedCheckIn.calculatedScore || analysis.distressScore || 50,
      riskLevel: analysis.level || "MODERATE",
      trajectory: analysis.trend || "STABLE",
      confidence: 0.88,
      contributingFactors: analysis.contributingFactors || [],
      factorBreakdown: analysis.factorPercentages || {},
      explanation: analysis.explanation,
      requiresHumanReview: Boolean(analysis.requiresHumanReview || decision.alert.requiresHumanReview),
      isExplicitSafetyConcern: Boolean(analysis.isExplicitSafetyConcern || checkIn.immediateSafetyConcern || checkIn.safety === "No")
    }).catch((err) => {
      console.warn("[ParticipantStore] Risk prediction persist notice:", err.message);
    });

    // Persist alert if newly created
    if (decision.isNewAlert && (decision.alert.requiresHumanReview || decision.alert.category === "SUPPORT_REQUEST" || decision.alert.category === "SAFETY_CONCERN")) {
      apiService.alerts.create({
        participantId: decision.alert.participantId,
        category: decision.alert.category,
        severity: decision.alert.severity,
        title: decision.alert.title,
        reason: decision.alert.reason,
        description: decision.alert.description,
        recommendedAction: decision.alert.recommendedAction,
        score: decision.alert.score,
        changeDelta: decision.alert.changeDelta,
        assignedTo: decision.alert.assignedTo,
        status: decision.alert.status,
        requiresHumanReview: decision.alert.requiresHumanReview,
        contributingFactors: decision.alert.contributingFactors,
        trajectory: decision.alert.trajectory
      }).catch((err) => {
        console.warn("[ParticipantStore] Alert persist notice:", err.message);
      });
    }

    return { participant: targetParticipant, alert: decision.alert, decision, analysis };
  },

  updateParticipantStatus: (participantId: string, status: CaseStatus) => {
    const participants = getStoredParticipants();
    const idx = participants.findIndex((p) => p.id === participantId);
    if (idx >= 0) {
      participants[idx] = {
        ...participants[idx],
        status,
        lastReviewDate: new Date().toISOString()
      };
      saveStoredParticipants(participants);
    }
    // Persist to backend
    apiService.participants.update(participantId, { status }).catch((err) => {
      console.warn("[ParticipantStore] Participant status update notice:", err.message);
    });
  },

  addParticipantNote: (participantId: string, note: SupportNote) => {
    const participants = getStoredParticipants();
    const idx = participants.findIndex((p) => p.id === participantId);
    if (idx >= 0) {
      participants[idx] = {
        ...participants[idx],
        notes: [note, ...(participants[idx].notes || [])]
      };
      saveStoredParticipants(participants);

      auditService.recordAuditEvent({
        actorId: "SW-001",
        actorRole: "SUPPORT_WORKER",
        actorName: note.author || "Support Worker",
        participantId,
        action: "SUPPORT_NOTE_ADDED",
        category: "SUPPORT",
        description: `Support case note recorded for participant ${participantId}: ${note.text.substring(0, 100)}`,
        severity: "INFO"
      });
    }
    // Persist note to backend
    apiService.participants.addNote(participantId, {
      author: note.author,
      text: note.text,
      actionTaken: note.actionTaken
    }).catch((err) => {
      console.warn("[ParticipantStore] Participant note persist notice:", err.message);
    });
  },

  assignWorker: (participantId: string, workerName: string) => {
    const participants = getStoredParticipants();
    const idx = participants.findIndex((p) => p.id === participantId);
    if (idx >= 0) {
      participants[idx] = {
        ...participants[idx],
        assignedWorker: workerName
      };
      saveStoredParticipants(participants);

      auditService.recordAuditEvent({
        actorId: "SW-001",
        actorRole: "SUPPORT_WORKER",
        actorName: workerName,
        participantId,
        action: "WORKER_ASSIGNED",
        category: "SUPPORT",
        description: `Support worker ${workerName} assigned to participant ${participantId}`,
        severity: "INFO"
      });
    }
    // Persist to backend
    apiService.participants.update(participantId, { assignedWorker: workerName }).catch((err) => {
      console.warn("[ParticipantStore] Assign worker persist notice:", err.message);
    });
  },

  getAlerts: (): Alert[] => {
    return getStoredAlerts();
  },

  /**
   * Complete Human Review Workflow Action
   */
  updateAlertStatus: (
    alertId: string,
    status: AlertStatus,
    decisionNotes: string,
    actionTaken: string,
    reviewedBy = "Dr. Sarah Jenkins, MSW"
  ) => {
    const alerts = getStoredAlerts();
    const idx = alerts.findIndex((a) => a.id === alertId);
    if (idx >= 0) {
      const alert = alerts[idx];
      const now = new Date().toISOString();

      alerts[idx] = {
        ...alert,
        status,
        decisionNotes,
        actionTaken,
        reviewedAt: now,
        reviewedBy,
        updatedAt: now
      };
      saveStoredAlerts(alerts);

      // Record Specific Audit Events based on action
      if (status === "ACKNOWLEDGED" || status === "IN_REVIEW") {
        auditService.recordAuditEvent({
          actorId: "SW-001",
          actorRole: "SUPPORT_WORKER",
          actorName: reviewedBy,
          participantId: alert.participantId,
          action: "ALERT_ACKNOWLEDGED",
          category: "ALERT",
          description: `Support worker acknowledged alert for ${alert.participantId}`,
          severity: "INFO"
        });
      } else if (status === "RESOLVED") {
        auditService.recordAuditEvent({
          actorId: "SW-001",
          actorRole: "SUPPORT_WORKER",
          actorName: reviewedBy,
          participantId: alert.participantId,
          action: "ALERT_RESOLVED",
          category: "ALERT",
          description: `Alert resolved for ${alert.participantId}`,
          severity: "INFO"
        });
      } else if (status === "FOLLOW_UP_ASSIGNED") {
        auditService.recordAuditEvent({
          actorId: "SW-001",
          actorRole: "SUPPORT_WORKER",
          actorName: reviewedBy,
          participantId: alert.participantId,
          action: "FOLLOW_UP_ASSIGNED",
          category: "FOLLOW_UP",
          description: `Follow-up assigned for ${alert.participantId}`,
          severity: "INFO"
        });
      } else if (status === "SAFETY_ESCALATED") {
        auditService.recordAuditEvent({
          actorId: "SW-001",
          actorRole: "SUPPORT_WORKER",
          actorName: reviewedBy,
          participantId: alert.participantId,
          action: "SAFETY_WORKFLOW_TRIGGERED",
          category: "SAFETY",
          description: `Emergency safety protocol triggered for participant ${alert.participantId}`,
          severity: "HIGH"
        });
      }

      // Record General Participant Review Audit Event
      auditService.recordAuditEvent({
        actorId: "SW-001",
        actorRole: "SUPPORT_WORKER",
        actorName: reviewedBy,
        participantId: alert.participantId,
        action: "PARTICIPANT_REVIEWED",
        category: "SUPPORT",
        description: `Support worker reviewed participant ${alert.participantId}`,
        details: `Action: ${actionTaken}. Notes: ${decisionNotes}`,
        severity: "INFO"
      });

      // If follow-up was assigned, update participant status and notify
      if (status === "FOLLOW_UP_ASSIGNED" || actionTaken.toLowerCase().includes("follow-up")) {
        participantStore.updateParticipantStatus(alert.participantId, "Needs follow-up");

        // Add follow-up record
        participantStore.addFollowUp({
          participantId: alert.participantId,
          alertId: alert.id,
          originalScore: alert.score,
          interventionType: actionTaken || "Scheduled Follow-up",
          interventionDate: now,
          workerName: reviewedBy,
          outcome: "pending",
          outcomeLabel: "Scheduled Follow-up in Progress",
          notes: decisionNotes || "Follow-up initiated during human review."
        });

        // Notify participant gently
        notificationService.createNotification({
          userId: alert.participantId,
          participantId: alert.participantId,
          category: "FOLLOW_UP_DUE",
          severity: "INFO",
          title: "Follow-up Scheduled",
          message: "Your support worker has scheduled a voluntary follow-up check-in.",
          actionLabel: "View Details",
          actionView: "participant_home"
        });
      } else if (status === "RESOLVED") {
        participantStore.updateParticipantStatus(alert.participantId, "Stable");
      }

      // Persist alert status to FastAPI backend
      apiService.alerts.update(alertId, {
        status,
        decisionNotes,
        actionTaken,
        reviewedBy
      }).catch((err) => {
        console.warn("[ParticipantStore] Alert status backend update notice:", err.message);
      });

      // Mark participant reviewed
      apiService.participants.markReviewed(alert.participantId).catch((err) => {
        console.warn("[ParticipantStore] Mark reviewed backend notice:", err.message);
      });
    }
  },

  // Backward compatibility method
  updateAlertDecision: (
    alertId: string,
    decision: "follow_up_scheduled" | "continue_monitoring" | "resolved" | "emergency_dispatched",
    notes: string
  ) => {
    const statusMap: Record<string, AlertStatus> = {
      follow_up_scheduled: "FOLLOW_UP_ASSIGNED",
      continue_monitoring: "MONITORING",
      resolved: "RESOLVED",
      emergency_dispatched: "SAFETY_ESCALATED"
    };

    const actionMap: Record<string, string> = {
      follow_up_scheduled: "Scheduled 1-on-1 counselor follow-up",
      continue_monitoring: "Marked for ongoing voluntary monitoring",
      resolved: "Case resolved after support interaction",
      emergency_dispatched: "Escalated to humanitarian safety protocol"
    };

    participantStore.updateAlertStatus(
      alertId,
      statusMap[decision] || "ACKNOWLEDGED",
      notes,
      actionMap[decision] || decision,
      "Dr. Sarah Jenkins, MSW"
    );
  },

  // Audit Logs (delegated to centralized auditService)
  getAuditLogs: (): AuditLogEntry[] => {
    return auditService.getAuditEvents();
  },

  addAuditLog: (entry: any): AuditLogEntry => {
    return auditService.recordAuditEvent({
      ...entry,
      action: entry.action || "ACTION_RECORDED",
      category: entry.category || "SUPPORT",
      description: entry.details || entry.description || "Audit entry"
    });
  },

  // Follow-ups & Outcomes
  getFollowUps: (): InterventionFollowUp[] => {
    return getStoredFollowUps();
  },

  addFollowUp: (followUp: Omit<InterventionFollowUp, "id">): InterventionFollowUp => {
    const followUps = getStoredFollowUps();
    const newFollowUp: InterventionFollowUp = {
      id: `fup-${Date.now()}-${Math.random().toString(36).substring(2, 6)}`,
      ...followUp
    };
    const updated = [newFollowUp, ...followUps];
    saveStoredFollowUps(updated);

    // Persist to backend API
    apiService.followUps.create({
      participantId: followUp.participantId,
      alertId: followUp.alertId,
      originalScore: followUp.originalScore,
      interventionType: followUp.interventionType,
      interventionDate: followUp.interventionDate,
      workerName: followUp.workerName,
      outcome: followUp.outcome,
      outcomeLabel: followUp.outcomeLabel,
      notes: followUp.notes
    }).catch((err) => {
      console.warn("[ParticipantStore] FollowUp backend persist notice:", err.message);
    });

    return newFollowUp;
  },

  updateFollowUp: (id: string, updates: Partial<InterventionFollowUp>) => {
    const followUps = getStoredFollowUps();
    const idx = followUps.findIndex(f => f.id === id);
    if (idx >= 0) {
      followUps[idx] = { ...followUps[idx], ...updates };
      saveStoredFollowUps(followUps);

      auditService.recordAuditEvent({
        actorId: "SW-001",
        actorRole: "SUPPORT_WORKER",
        actorName: "Dr. Sarah Jenkins, MSW",
        participantId: followUps[idx].participantId,
        action: "FOLLOW_UP_UPDATED",
        category: "FOLLOW_UP",
        description: `Follow-up outcome updated for participant ${followUps[idx].participantId} (${updates.outcomeLabel || updates.outcome || "updated"})`,
        severity: "INFO"
      });
    }
  },

  // Notification Preferences
  getParticipantNotificationPreferences: (participantId: string): ParticipantNotificationPreferences => {
    try {
      const raw = localStorage.getItem(`${NOTIF_PREFS_KEY}_${participantId}`);
      if (raw) return JSON.parse(raw);
    } catch {}
    return {
      checkInReminders: true,
      supportUpdates: true,
      followUpReminders: true,
      wellbeingUpdates: true,
      safetyGuidanceEnforced: true
    };
  },

  saveParticipantNotificationPreferences: (participantId: string, prefs: ParticipantNotificationPreferences) => {
    try {
      localStorage.setItem(`${NOTIF_PREFS_KEY}_${participantId}`, JSON.stringify({ ...prefs, safetyGuidanceEnforced: true }));
      notifyChange();
    } catch (e) {
      console.error("Failed to save participant notification preferences", e);
    }
  },

  getWorkerNotificationPreferences: (workerId: string): WorkerNotificationPreferences => {
    try {
      const raw = localStorage.getItem(`${NOTIF_PREFS_KEY}_worker_${workerId}`);
      if (raw) return JSON.parse(raw);
    } catch {}
    return {
      priorityAlerts: true,
      humanReviewAlerts: true,
      supportRequests: true,
      followUpReminders: true,
      dailySummary: true
    };
  },

  saveWorkerNotificationPreferences: (workerId: string, prefs: WorkerNotificationPreferences) => {
    try {
      localStorage.setItem(`${NOTIF_PREFS_KEY}_worker_${workerId}`, JSON.stringify(prefs));
      notifyChange();
    } catch (e) {
      console.error("Failed to save worker notification preferences", e);
    }
  },

  // Reset a specific participant's data (clears checkins for new participant, or resets demo participant)
  resetParticipantData: (participantId: string) => {
    const participants = getStoredParticipants();
    const idx = participants.findIndex((p) => p.id === participantId);
    if (idx >= 0) {
      if (participantId === "P-1042") {
        // Reset demo participant to initial seeded state
        const demoOriginal = MOCK_PARTICIPANTS.find((p) => p.id === "P-1042");
        if (demoOriginal) {
          participants[idx] = JSON.parse(JSON.stringify(demoOriginal));
        }
      } else {
        // Clear all check-ins for the custom user
        participants[idx] = {
          ...participants[idx],
          checkIns: [],
          status: "Stable",
          notes: []
        };
      }
      saveStoredParticipants(participants);

      // Remove non-seeded alerts for this participant
      const alerts = getStoredAlerts();
      const filteredAlerts = alerts.filter(
        (a) => a.participantId !== participantId || (participantId === "P-1042" && a.id.startsWith("alt-1"))
      );
      saveStoredAlerts(filteredAlerts);

      // Clear notifications for this participant if not demo
      if (participantId !== "P-1042") {
        notificationService.clearNotifications(participantId);
      }
    }
  },

  getLatestAnalysisForParticipant: (participantId: string): CheckInAnalysis | null => {
    const p = participantStore.getParticipantById(participantId);
    if (!p || p.checkIns.length === 0) return null;
    const latest = p.checkIns[p.checkIns.length - 1];
    if (latest.analysis) return latest.analysis;
    const prev = p.checkIns.length > 1 ? p.checkIns[p.checkIns.length - 2] : null;
    return calculateCheckInAnalysis(latest, prev, p.checkIns);
  },

  // User management for persistent cross-login lookup
  getRegisteredUsers: (): User[] => {
    try {
      const raw = localStorage.getItem(USERS_KEY);
      return raw ? JSON.parse(raw) : [];
    } catch {
      return [];
    }
  },

  findUserByEmail: (email: string): User | null => {
    const users = participantStore.getRegisteredUsers();
    return users.find((u) => u.email.toLowerCase() === email.trim().toLowerCase()) || null;
  },

  saveUser: (user: User) => {
    try {
      const users = participantStore.getRegisteredUsers();
      const idx = users.findIndex((u) => u.email.toLowerCase() === user.email.toLowerCase());
      if (idx >= 0) {
        users[idx] = user;
      } else {
        users.push(user);
      }
      localStorage.setItem(USERS_KEY, JSON.stringify(users));
    } catch (e) {
      console.error("Failed to save user", e);
    }
  }
};

import {
  CheckIn,
  CheckInAnalysis,
  DistressLevel,
  Recommendation,
  RecommendationCategory
} from "../types";
import { ALERT_CONFIG } from "./alertConfig";
import { calculateRawScore } from "./riskEngine";

/**
 * AURA Recommendation and Supportive Reflection Engine
 * 
 * IMPORTANT:
 * AURA is a non-diagnostic, decision-support prototype.
 * It provides non-clinical wellbeing summaries and compassionate guidance.
 * It does NOT replace medical or psychiatric evaluation.
 */

/**
 * Classifies numerical score into standard prototype distress level
 */
export function getDistressLevel(score: number): { level: DistressLevel; label: string } {
  if (score <= ALERT_CONFIG.LOW_DISTRESS_MAX) {
    return { level: "LOW", label: "Calmer Reported Distress" };
  } else if (score <= ALERT_CONFIG.MILD_MAX) {
    return { level: "MILD", label: "Mild / Monitoring" };
  } else if (score <= ALERT_CONFIG.MODERATE_MAX) {
    return { level: "MODERATE", label: "Moderate Reported Distress" };
  } else if (score <= ALERT_CONFIG.ELEVATED_MAX) {
    return { level: "ELEVATED", label: "Elevated Reported Distress" };
  } else if (score <= ALERT_CONFIG.HIGH_MAX) {
    return { level: "HIGH", label: "High Reported Distress" };
  } else {
    return { level: "VERY_HIGH", label: "High-Priority Wellbeing Signal" };
  }
}

/**
 * Calculates factor percentage representations for visual breakdown (Response Patterns)
 */
export function calculateFactorPercentages(checkIn: CheckIn) {
  // Stress: 1 (calm) -> 15%, 5 (very stressed) -> 95%
  const stressPct = Math.round(15 + ((checkIn.stress - 1) / 4) * 80);

  // Sleep concern: 5 (good) -> 10%, 1 (very difficult) -> 90%
  const sleepPct = Math.round(10 + ((5 - checkIn.sleep) / 4) * 80);

  // Emotional wellbeing concern: 5 (good) -> 10%, 1 (very difficult) -> 85%
  const wellbeingPct = Math.round(10 + ((5 - checkIn.wellbeing) / 4) * 75);

  // Social isolation concern: 5 (connected) -> 10%, 1 (isolated) -> 80%
  const socialPct = Math.round(10 + ((5 - checkIn.connection) / 4) * 70);

  // Functioning / strain proxy
  const functioningPct = Math.round((stressPct * 0.4 + wellbeingPct * 0.4 + sleepPct * 0.2));

  return {
    stress: Math.min(100, Math.max(10, stressPct)),
    sleep: Math.min(100, Math.max(10, sleepPct)),
    emotionalWellbeing: Math.min(100, Math.max(10, wellbeingPct)),
    socialConnection: Math.min(100, Math.max(10, socialPct)),
    functioning: Math.min(100, Math.max(10, functioningPct))
  };
}

/**
 * Generates explainable, understandable factors that contributed to the score
 */
export function generateContributingFactors(checkIn: CheckIn): { factors: string[]; explanationPoints: string[] } {
  const factors: string[] = [];
  const explanationPoints: string[] = [];

  // Perceived Safety
  if (checkIn.immediateSafetyConcern) {
    factors.push("Immediate safety alert recorded");
    explanationPoints.push("You indicated an immediate safety concern in your responses.");
  } else if (checkIn.safety === "No") {
    factors.push("Reported unsafe environment");
    explanationPoints.push("You reported not feeling safe in your current surroundings.");
  } else if (checkIn.safety === "Unsure") {
    factors.push("Safety uncertainty reported");
    explanationPoints.push("You expressed uncertainty regarding physical or emotional security.");
  }

  // Stress
  if (checkIn.stress >= 4) {
    factors.push("Elevated stress & overwhelm");
    explanationPoints.push("You reported high day-to-day stress or feeling overwhelmed.");
  } else if (checkIn.stress === 3) {
    factors.push("Moderate stress");
  }

  // Sleep
  if (checkIn.sleep <= 2) {
    factors.push("Disrupted sleep & rest");
    explanationPoints.push("You indicated restless or interrupted sleep recently.");
  }

  // Emotional Wellbeing
  if (checkIn.wellbeing <= 2) {
    factors.push("Challenging emotional state");
    explanationPoints.push("You noted a particularly difficult emotional or mental state today.");
  }

  // Social Connection
  if (checkIn.connection <= 2) {
    factors.push("Feelings of isolation");
    explanationPoints.push("You reported feeling mostly alone or lacking trusted connection.");
  }

  // Explicit Support Request
  if (checkIn.supportRequested) {
    factors.push("Voluntary support requested");
    explanationPoints.push("You requested a voluntary conversation with a support worker.");
  }

  // Reflection Language Signal (optional secondary factor)
  if (checkIn.reflection?.analysis) {
    const sent = checkIn.reflection.analysis.sentiment;
    if (sent === "stressed" || sent === "overwhelmed") {
      factors.push("Reflection language signal");
      explanationPoints.push("Your written/voice reflection contained language associated with stress or fatigue.");
    } else if (sent === "positive") {
      factors.push("Positive reflection language");
    }
  }

  if (factors.length === 0) {
    factors.push("Calm baseline responses across all categories");
    explanationPoints.push("Your responses reflect a calm, relatively balanced baseline.");
  }

  return { factors, explanationPoints };
}

/**
 * Builds the top-level explainability narrative (Why did AURA generate this result?)
 */
export function buildExplainabilityNarrative(
  score: number,
  points: string[],
  change: number,
  isExplicitSafety: boolean
): string {
  if (isExplicitSafety) {
    return "An immediate safety priority was signaled in your response. This bypasses routine score calculation to ensure immediate support options are available.";
  }

  if (points.length === 0 || score <= ALERT_CONFIG.LOW_DISTRESS_MAX) {
    return "Your responses reflect low reported distress across stress, sleep, safety, and social connection. No immediate areas of strain were flagged.";
  }

  const primaryDrivers = points.slice(0, 3).join(" ");
  if (change >= 15) {
    return `Your indicator is elevated mainly because ${primaryDrivers} Additionally, your reported distress increased significantly (+${change} pts) compared to your previous check-in.`;
  }

  if (score >= 75) {
    return `Your indicator is in the higher range mainly because ${primaryDrivers}`;
  }

  return `AURA identified moderate response patterns because ${primaryDrivers}`;
}

/**
 * Generates compassionate, non-clinical supportive reflection
 */
export function generateSupportiveReflection(
  score: number,
  checkIn: CheckIn,
  change: number,
  isExplicitSafety: boolean
): string {
  if (isExplicitSafety) {
    return "Your safety and wellbeing are the absolute priority. Please consider connecting right now with one of the available crisis contacts or reaching out to someone you trust.";
  }

  if (score >= 86) {
    return "It sounds like you have been carrying an intense level of stress or difficulty recently. You don't have to carry this all on your own. Consider taking one small, gentle step today toward rest, and connecting with someone you trust or a qualified support worker.";
  }

  if (score >= 75) {
    if (checkIn.sleep <= 2 && checkIn.stress >= 4) {
      return "It sounds like stress and disrupted sleep have been making things difficult recently. You don't have to handle everything at once. Consider taking one manageable step toward rest, and reaching out for support if that feels comfortable.";
    }
    return "Some of your recent responses suggest that you may be experiencing a higher level of distress than usual. Taking things one day at a time and talking with someone you trust can offer meaningful relief.";
  }

  if (change <= -10) {
    return "Your latest responses suggest things may be feeling somewhat easier than before. It's okay to take things one day at a time and hold on to what has been helpful.";
  }

  if (change >= 15) {
    return "Your responses suggest a noticeable increase in stress or difficulty since your last check-in. Remember that fluctuations are natural; giving yourself extra patience and space right now is important.";
  }

  if (score <= ALERT_CONFIG.LOW_DISTRESS_MAX) {
    return "Your responses suggest a relatively calmer period right now. Keep using the check-in whenever you feel it would be useful to check in with yourself.";
  }

  if (score <= ALERT_CONFIG.MILD_MAX) {
    return "Your responses suggest manageable day-to-day levels. Taking short moments for rest and routine can help maintain your stability.";
  }

  return "Thank you for taking a moment to reflect today. You don't have to have everything figured out right now. Focus on what is manageable for you today.";
}

/**
 * Generates ranked, personalized recommendations based on actual answers
 */
export function generateRecommendations(
  analysis: CheckInAnalysis,
  checkIn: CheckIn,
  previousCheckIn: CheckIn | null
): {
  recommendations: Recommendation[];
  primaryAction: string;
  supportiveMessage: string;
} {
  const recommendations: Recommendation[] = [];
  const score = analysis.distressScore;
  const change = analysis.change ?? 0;

  // 1. SAFETY (Highest priority if explicit concern)
  if (analysis.isExplicitSafetyConcern) {
    recommendations.push({
      category: "SAFETY",
      title: "Immediate Safety & Crisis Resources",
      description: "Please access available immediate crisis hotlines, on-site shelter coordinators, or trusted community workers.",
      priority: "HIGH",
      actionLabel: "Access Crisis Help",
      actionType: "emergency"
    });
  }

  // 2. PROFESSIONAL SUPPORT / HUMAN WORKER (For score >= 75 or explicit support request)
  if (score >= 75 || checkIn.supportRequested) {
    recommendations.push({
      category: "PROFESSIONAL_SUPPORT",
      title: "Consider additional support",
      description: "Because your responses indicate a higher level of distress, you may benefit from speaking with a qualified mental-health professional or support worker.",
      priority: score >= 86 ? "HIGH" : "MEDIUM",
      actionLabel: "Talk to a Support Worker",
      actionType: "support_contact"
    });
  }

  // 3. EMOTIONAL SUPPORT (If score >= 60)
  if (score >= 60 && score < 75 && !checkIn.supportRequested) {
    recommendations.push({
      category: "EMOTIONAL_SUPPORT",
      title: "Consider talking to someone",
      description: "Talking with a trusted person or qualified support professional may help you feel less alone and give you space to talk about what you're experiencing.",
      priority: "MEDIUM",
      actionLabel: "View Support Options",
      actionType: "support_options"
    });
  }

  // 4. STRESS MANAGEMENT (If stress >= 4)
  if (checkIn.stress >= 4) {
    recommendations.push({
      category: "STRESS",
      title: "Managing stress",
      description: "Consider taking short breaks, using slow breathing or grounding exercises, and breaking overwhelming tasks into smaller steps. You don't have to manage everything at once.",
      priority: "HIGH",
      actionLabel: "View Calming Techniques",
      actionType: "calm"
    });
  }

  // 5. SLEEP SUPPORT (If sleep <= 2)
  if (checkIn.sleep <= 2) {
    recommendations.push({
      category: "SLEEP",
      title: "Sleep support",
      description: "You may find it helpful to keep a consistent sleep and wake time, reduce stimulating activities close to bedtime, and create a quieter sleep environment where possible. If sleep difficulties continue, consider discussing them with a qualified professional.",
      priority: "MEDIUM",
      actionLabel: "Sleep Guidance",
      actionType: "sleep"
    });
  }

  // 6. SOCIAL CONNECTION (If connection <= 2)
  if (checkIn.connection <= 2) {
    recommendations.push({
      category: "SOCIAL",
      title: "Connection may help",
      description: "If it feels comfortable, consider reaching out to someone you trust, such as a friend, family member, community worker, or peer support contact.",
      priority: "MEDIUM",
      actionLabel: "Explore Community",
      actionType: "social"
    });
  }

  // 7. ROUTINE RECOMMENDATION (If wellbeing is difficult, or stress is high)
  if (checkIn.wellbeing <= 2 || checkIn.stress >= 4) {
    recommendations.push({
      category: "ROUTINE",
      title: "Consider a gentler daily routine",
      description: "Try keeping a simple daily structure around meals, rest, personal care, and activities you find manageable. Avoid adding unnecessary burdens.",
      priority: "LOW",
      actionLabel: "Routine Tips",
      actionType: "routine"
    });
  }

  // 8. FOLLOW-UP / VOLUNTARY MONITORING (For lower scores or general progress)
  if (score <= ALERT_CONFIG.MILD_MAX && recommendations.length < 3) {
    recommendations.push({
      category: "FOLLOW_UP",
      title: "Continue voluntary check-ins",
      description: "Keep tracking your wellbeing at your own pace whenever it feels helpful. Continued reflections help identify your personal baseline.",
      priority: "LOW",
      actionLabel: "Schedule Next Reminder",
      actionType: "reminder"
    });

    recommendations.push({
      category: "ROUTINE",
      title: "Maintain routines that feel helpful",
      description: "Continue the daily habits, connections, and restful practices that currently support your sense of balance.",
      priority: "LOW"
    });
  }

  // 9. DYNAMIC TREND ADJUSTMENT
  if (change >= 15) {
    recommendations.unshift({
      category: "FOLLOW_UP",
      title: "Increasing distress pattern",
      description: `Your current indicator is +${change} points higher than your previous check-in. Consider checking in again soon or connecting with your chosen support option.`,
      priority: "HIGH"
    });
  } else if (change <= -10) {
    recommendations.push({
      category: "FOLLOW_UP",
      title: "Improvement detected",
      description: `Your reported distress indicator has decreased by ${Math.abs(change)} points since your previous check-in. Continue the supportive routines that are working for you.`,
      priority: "LOW"
    });
  }

  // Cap recommendations to top 3 to 4 to avoid cognitive overwhelm
  const ranked = recommendations
    .sort((a, b) => {
      const pOrder = { HIGH: 0, MEDIUM: 1, LOW: 2 };
      return pOrder[a.priority] - pOrder[b.priority];
    })
    .slice(0, 4);

  // Primary Action determination for "What you can do now"
  let primaryAction = "Continue your normal routine and check in again when you feel comfortable.";
  if (analysis.isExplicitSafetyConcern) {
    primaryAction = "Please use the available immediate support and emergency resources.";
  } else if (score >= 86) {
    primaryAction = "Consider connecting with a qualified support professional or trusted person today. A support worker has also been alerted for review.";
  } else if (score >= 75) {
    primaryAction = "Consider connecting with a qualified support professional. A support worker may also review your check-in.";
  } else if (score >= 61) {
    primaryAction = "Consider talking with someone you trust or connecting with your chosen support option.";
  } else if (score >= 41) {
    primaryAction = "Consider taking some time for rest and establishing a gentle, manageable routine today.";
  }

  const supportiveMessage = generateSupportiveReflection(
    score,
    checkIn,
    change,
    analysis.isExplicitSafetyConcern
  );

  return {
    recommendations: ranked,
    primaryAction,
    supportiveMessage
  };
}

/**
 * MASTER FUNCTION: Analyzes a check-in completely and returns CheckInAnalysis
 */
export function calculateCheckInAnalysis(
  current: CheckIn,
  previous: CheckIn | null,
  history: CheckIn[] = []
): CheckInAnalysis {
  // Score is calculated from actual responses
  const score = current.calculatedScore ?? calculateRawScore(current);
  const prevScore = previous ? (previous.calculatedScore ?? calculateRawScore(previous)) : undefined;
  const change = prevScore !== undefined ? score - prevScore : undefined;

  const { level, label: levelLabel } = getDistressLevel(score);

  // Explicit safety condition
  const isExplicitSafety = Boolean(
    current.immediateSafetyConcern === true ||
    current.safety === "No" ||
    current.safety === "concern"
  );

  // Trend classification
  let trend: "IMPROVING" | "STABLE" | "INCREASING" | "RAPID_INCREASE" = "STABLE";
  if (change !== undefined) {
    if (change >= 15) trend = "RAPID_INCREASE";
    else if (change > 3) trend = "INCREASING";
    else if (change <= -10) trend = "IMPROVING";
  }

  // Factor percentage breakdown
  const factorPercentages = calculateFactorPercentages(current);

  // Contributing factors & explanations
  const { factors, explanationPoints } = generateContributingFactors(current);
  const explanation = buildExplainabilityNarrative(score, explanationPoints, change ?? 0, isExplicitSafety);

  // Partial analysis object to generate recommendations
  const partialAnalysis: CheckInAnalysis = {
    checkInId: current.id,
    participantId: current.participantId,
    distressScore: score,
    level,
    levelLabel,
    previousScore: prevScore,
    change,
    trend,
    factors: {
      stress: current.stress,
      sleep: current.sleep,
      mood: current.wellbeing,
      safety: current.safety,
      socialConnection: current.connection,
      functioning: current.wellbeing
    },
    factorPercentages,
    contributingFactors: factors,
    explanation,
    explanationPoints,
    recommendations: [],
    primaryAction: "",
    supportiveMessage: "",
    requiresHumanReview: score >= 75 || isExplicitSafety || current.supportRequested,
    isExplicitSafetyConcern: isExplicitSafety,
    createdAt: current.timestamp || new Date().toISOString()
  };

  const { recommendations, primaryAction, supportiveMessage } = generateRecommendations(
    partialAnalysis,
    current,
    previous
  );

  partialAnalysis.recommendations = recommendations;
  partialAnalysis.primaryAction = primaryAction;
  partialAnalysis.supportiveMessage = supportiveMessage;

  return partialAnalysis;
}

import { ReflectionAnalysisResult, LanguageSignalCategory } from "../types";

/**
 * AURA Contextual Reflection Language Analysis Engine
 * 
 * CORE PRINCIPLES:
 * 1. Language-based signal ONLY (not a clinical diagnostic assessment or emotion detection).
 * 2. Processes the ACTUAL submitted text, not mock or pre-seeded data.
 * 3. Never equates a single keyword (e.g., "noise", "sleep", "happy") with an isolated verdict.
 * 4. Recognizes context, contrastive clauses ("worried... but feeling much better"), and mixed sentiments.
 * 5. Transparently outputs contributing patterns and plain-language explanations.
 */

interface PatternDefinition {
  category: LanguageSignalCategory;
  sentiment: ReflectionAnalysisResult["sentiment"];
  regexList: RegExp[];
  patternDescriptions: string[];
}

// Word pattern libraries
const PATTERNS = {
  // Explicit immediate safety & danger phrases
  urgentSafety: [
    /\b(immediate danger|someone is hurting me|violence|attacked|threatened|want to end my life|suicide|self-harm|kill myself|emergency help)\b/i
  ],

  // Positive & hopeful language
  positiveHope: [
    /\b(happy|joyful|wonderful|grateful|blessed|excited|hopeful|optimistic|peaceful|content|great day|good day|feeling good|felt great|proud|relieved|energized)\b/i,
    /\b(looking forward to|future feels brighter|feeling much better|feel better|improved|making progress|things are getting better)\b/i
  ],

  // Social connection
  socialConnection: [
    /\b(met (?:my )?friends|talked with (?:my )?family|community|neighbors|supportive|connected|spent time with|gathering|shared a meal|group)\b/i
  ],

  // Overwhelm & burden
  overwhelmBurden: [
    /\b(overwhelmed|exhausted|burned out|breaking point|cannot cope|can't cope|too much to handle|drowning in|at my limit|helpless|hopeless|crushed)\b/i,
    /\b(unbearable|drained|no energy left|completely depleted)\b/i
  ],

  // Stress & tension
  stressTension: [
    /\b(stress|stressed|tense|tension|anxious|anxiety|worried|worry|nervous|panicked|panicking|under pressure|frustrated|irritated|strained)\b/i
  ],

  // Sleep disruptions
  sleepIssues: [
    /\b(haven't been sleeping|can't sleep|cannot sleep|insomnia|trouble sleeping|nightmares|bad dreams|waking up constantly|restless sleep|tossing and turning|sleep deprivation)\b/i
  ],

  // Restful sleep
  sleepPositive: [
    /\b(slept well|restful sleep|good night's sleep|woke up refreshed|peaceful night)\b/i
  ],

  // Environmental safety & security concerns
  environmentalConcerns: [
    /\b(noise at night|noisy shelter|unsafe environment|uncomfortable space|crowded shelter|scared at night|lack of privacy|unstable shelter)\b/i
  ],

  // Routine & neutral daily activities
  neutralRoutine: [
    /\b(normal|routine|ordinary|went to work|cooked dinner|ran errands|cleaned|did chores|regular day|nothing special|uneventful|usual)\b/i
  ],

  // Support seeking
  supportSeeking: [
    /\b(need to talk|want to speak to someone|need help|guidance|counselor|support worker|advice|asking for support)\b/i
  ],

  // Contrastive / Concessive conjunctions that signal nuance & mixed states
  contrastive: [
    /\b(but|however|although|though|yet|on the other hand|even though|nevertheless|despite)\b/i
  ]
};

export function analyzeReflection(rawText: string, isDemoSample: boolean = false): ReflectionAnalysisResult {
  const text = (rawText || "").trim();

  // Test Case E & F: Empty reflection
  if (!text || text.length === 0) {
    return {
      sentiment: "none",
      languageSignal: "None",
      contributingPatterns: [],
      keywords: [],
      factors: [],
      explanation: "No reflection text provided.",
      isDemoSample: false,
      hasUrgentSafetyMention: false
    };
  }

  const lower = text.toLowerCase();
  const contributingPatterns: string[] = [];
  const matchedKeywords: string[] = [];
  const factors: string[] = [];

  // Check 1: Immediate Safety Concerns
  let hasUrgentSafety = false;
  for (const regex of PATTERNS.urgentSafety) {
    const match = text.match(regex);
    if (match) {
      hasUrgentSafety = true;
      contributingPatterns.push(`explicit mention of safety concern or crisis language: "${match[0]}"`);
      matchedKeywords.push(match[0]);
    }
  }

  if (hasUrgentSafety) {
    return {
      sentiment: "safety_concern",
      languageSignal: "Safety-related language",
      contributingPatterns,
      keywords: matchedKeywords,
      factors: ["Immediate safety keyword detected in text", "Urgent humanitarian protocol guidance recommended"],
      explanation: "The reflection contains direct statements regarding urgent safety or crisis needs. Human review and emergency guidance are prioritized.",
      isDemoSample,
      hasUrgentSafetyMention: true
    };
  }

  // Check 2: Pattern detections across dimensions
  const hasPositiveHope = PATTERNS.positiveHope.some(r => {
    const m = text.match(r);
    if (m) {
      matchedKeywords.push(m[0]);
      return true;
    }
    return false;
  });

  const hasSocial = PATTERNS.socialConnection.some(r => {
    const m = text.match(r);
    if (m) {
      matchedKeywords.push(m[0]);
      return true;
    }
    return false;
  });

  const hasOverwhelm = PATTERNS.overwhelmBurden.some(r => {
    const m = text.match(r);
    if (m) {
      matchedKeywords.push(m[0]);
      return true;
    }
    return false;
  });

  const hasStress = PATTERNS.stressTension.some(r => {
    const m = text.match(r);
    if (m) {
      matchedKeywords.push(m[0]);
      return true;
    }
    return false;
  });

  const hasSleepIssues = PATTERNS.sleepIssues.some(r => {
    const m = text.match(r);
    if (m) {
      matchedKeywords.push(m[0]);
      return true;
    }
    return false;
  });

  const hasSleepPositive = PATTERNS.sleepPositive.some(r => {
    const m = text.match(r);
    if (m) {
      matchedKeywords.push(m[0]);
      return true;
    }
    return false;
  });

  const hasEnvConcerns = PATTERNS.environmentalConcerns.some(r => {
    const m = text.match(r);
    if (m) {
      matchedKeywords.push(m[0]);
      return true;
    }
    return false;
  });

  const hasNeutralRoutine = PATTERNS.neutralRoutine.some(r => {
    const m = text.match(r);
    if (m) {
      matchedKeywords.push(m[0]);
      return true;
    }
    return false;
  });

  const hasSupportSeeking = PATTERNS.supportSeeking.some(r => {
    const m = text.match(r);
    if (m) {
      matchedKeywords.push(m[0]);
      return true;
    }
    return false;
  });

  const hasContrastive = PATTERNS.contrastive.some(r => r.test(text));

  // Build pattern list
  if (hasPositiveHope) contributingPatterns.push("positive outlook & hopeful language");
  if (hasSocial) contributingPatterns.push("active social connection & support network");
  if (hasSleepPositive) contributingPatterns.push("restful sleep mentioned");
  if (hasOverwhelm) contributingPatterns.push("feelings of overwhelm or depletion");
  if (hasStress) contributingPatterns.push("stress, tension, or anxious phrasing");
  if (hasSleepIssues) contributingPatterns.push("sleep interruption or insomnia mentions");
  if (hasEnvConcerns) contributingPatterns.push("environmental or living condition stressors");
  if (hasNeutralRoutine) contributingPatterns.push("routine daily activities described");
  if (hasSupportSeeking) contributingPatterns.push("interest in talking with a support worker");

  const positiveSignalsCount = (hasPositiveHope ? 1 : 0) + (hasSocial ? 1 : 0) + (hasSleepPositive ? 1 : 0);
  const negativeSignalsCount = (hasOverwhelm ? 2 : 0) + (hasStress ? 1 : 0) + (hasSleepIssues ? 1 : 0) + (hasEnvConcerns ? 1 : 0);

  // CONTEXTUAL EVALUATION (TEST CASES A, B, C, D)

  // TEST D: Mixed / Contrastive text (e.g., "I am worried about the noise at night, but I am feeling much better this week.")
  if (hasContrastive && positiveSignalsCount > 0 && negativeSignalsCount > 0) {
    return {
      sentiment: "mixed",
      languageSignal: "Mixed language signal",
      contributingPatterns,
      keywords: Array.from(new Set(matchedKeywords)),
      factors: [
        "Contrastive statement with both challenges and improvement present",
        "Acknowledges localized concern while noting overall positive trajectory"
      ],
      explanation: "The reflection expresses mixed sentiments, acknowledging specific concerns while simultaneously noting areas of improvement or hope. Contextual nuance is preserved.",
      isDemoSample,
      hasUrgentSafetyMention: false
    };
  }

  // TEST A: Purely or predominantly positive / hopeful (e.g., "I had a really happy day. I met my friends and feel hopeful about tomorrow.")
  if (positiveSignalsCount > 0 && negativeSignalsCount === 0) {
    const factorsList: string[] = ["Positive framing in voluntary narrative"];
    if (hasSocial) factorsList.push("Supportive interpersonal connection mentioned");
    if (hasPositiveHope) factorsList.push("Expressions of optimism and hope for the future");

    return {
      sentiment: "positive",
      languageSignal: "Positive / hopeful language",
      contributingPatterns,
      keywords: Array.from(new Set(matchedKeywords)),
      factors: factorsList,
      explanation: "The reflection contains language associated with positive outlook, emotional grounding, and supportive social connection.",
      isDemoSample,
      hasUrgentSafetyMention: false
    };
  }

  // TEST B: Overwhelm / Burden / High Stress (e.g., "I feel overwhelmed and exhausted. I haven't been sleeping properly.")
  if (hasOverwhelm || (negativeSignalsCount >= 2 && positiveSignalsCount === 0)) {
    const factorsList: string[] = [];
    if (hasOverwhelm) factorsList.push("Mentions feeling overwhelmed or exhausted");
    if (hasSleepIssues) factorsList.push("Mentions difficulty sleeping or disrupted rest");
    if (hasEnvConcerns) factorsList.push("Describes environmental or shelter stress");
    if (hasStress) factorsList.push("Mentions emotional tension");

    const signalLabel: LanguageSignalCategory = hasOverwhelm 
      ? "Overwhelm / burden language" 
      : "Stress-related language";

    return {
      sentiment: hasOverwhelm ? "overwhelmed" : "stressed",
      languageSignal: signalLabel,
      contributingPatterns,
      keywords: Array.from(new Set(matchedKeywords)),
      factors: factorsList,
      explanation: "The reflection contains language associated with elevated stress, emotional exhaustion, or sleep strain. This provides supportive context for human review.",
      isDemoSample,
      hasUrgentSafetyMention: false
    };
  }

  // Isolated stress or sleep issue (e.g., "A bit stressed about moving")
  if (negativeSignalsCount > 0 && positiveSignalsCount === 0) {
    return {
      sentiment: "stressed",
      languageSignal: hasSleepIssues ? "Sleep-related language" : "Stress-related language",
      contributingPatterns,
      keywords: Array.from(new Set(matchedKeywords)),
      factors: ["Mild stress or sleep disturbance phrasing in reflection"],
      explanation: "The reflection includes phrasing related to situational stress or sleep difficulty.",
      isDemoSample,
      hasUrgentSafetyMention: false
    };
  }

  // TEST C: Neutral / Ordinary routine (e.g., "Today was normal. I went to work and cooked dinner.")
  if (hasNeutralRoutine || (positiveSignalsCount === 0 && negativeSignalsCount === 0 && text.length > 0)) {
    return {
      sentiment: "neutral",
      languageSignal: "Neutral / ordinary language",
      contributingPatterns: contributingPatterns.length > 0 ? contributingPatterns : ["neutral daily description"],
      keywords: Array.from(new Set(matchedKeywords)),
      factors: ["Everyday narrative phrasing without strong emotional valence"],
      explanation: "The reflection describes routine daily events or neutral observations without strong distress or elevated positive indicators.",
      isDemoSample,
      hasUrgentSafetyMention: false
    };
  }

  // Fallback for mixed without explicit contrastive conjunctions
  return {
    sentiment: "mixed",
    languageSignal: "Mixed language signal",
    contributingPatterns,
    keywords: Array.from(new Set(matchedKeywords)),
    factors: ["Multiple mixed emotional markers identified in narrative"],
    explanation: "The reflection reflects diverse thoughts with both supportive and challenging aspects.",
    isDemoSample,
    hasUrgentSafetyMention: false
  };
}

import { CheckIn, TrajectoryAnalysis, SupportRecommendation, SupportPriority } from "../types";

/**
 * AI Support Recommendation Engine (Humanitarian Decision-Support)
 * 
 * Strict Ethical Principles:
 * 1. NEVER recommend medication.
 * 2. NEVER diagnose any mental-health or medical condition.
 * 3. NEVER recommend psychiatric treatments or clinical protocols autonomously.
 * 4. NEVER automatically contact law enforcement or authorities.
 * 5. ALWAYS require human review for non-routine support recommendations.
 */

export const generateSupportRecommendation = (
  currentCheckIn?: CheckIn | null,
  trajectory?: TrajectoryAnalysis | null,
  previousSupportRequestCount: number = 0
): SupportRecommendation => {
  if (!currentCheckIn) {
    return {
      primaryRecommendation: "Awaiting baseline reflection or check-in.",
      priority: "Routine",
      conversationFocus: "Initial voluntary introduction, explaining safety protocols, and setting preferences",
      resources: [
        "AURA Welcome & Safety Guide",
        "Confidentiality and Consent Overview",
        "24/7 Crisis Support Numbers"
      ],
      rationale: "No check-ins have been logged yet for this participant.",
      requiresHumanReview: false
    };
  }

  const traj = trajectory || {
    direction: "stable" as const,
    rateOfChange: 0,
    consecutiveIncreases: 0,
    confidence: "Low" as const,
    category: "Stable Low Distress" as const,
    summaryDescription: "Baseline reflection recorded.",
    currentScore: currentCheckIn.calculatedScore || 30,
    previousScore: null,
    pointsCount: 1,
    recoveringAfterSupport: false
  };

  // Case 1: Immediate safety concern reported directly by participant
  if (currentCheckIn.immediateSafetyConcern || currentCheckIn.safety === "No") {
    return {
      primaryRecommendation: "Follow emergency/safety protocol and seek immediate human assistance.",
      priority: "Urgent",
      conversationFocus: "Immediate physical and emotional safety, grounding, and crisis support access",
      resources: [
        "National 24/7 Crisis Helplines directory",
        "On-site humanitarian welfare officer contact",
        "Guided grounding and immediate safety plan"
      ],
      rationale: "Participant self-reported immediate safety concern or acute distress.",
      requiresHumanReview: true
    };
  }

  // Case 2: Repeated voluntary support requests
  if (currentCheckIn.supportRequested && previousSupportRequestCount >= 1) {
    return {
      primaryRecommendation: "Prioritize human follow-up.",
      priority: "Follow-up Recommended",
      conversationFocus: "Direct counselor check-in regarding recurring support requests",
      resources: [
        "Humanitarian case worker direct messaging",
        "Scheduled 1-on-1 support conversation",
        "Community peer circle"
      ],
      rationale: "Participant has voluntarily requested support across consecutive check-ins.",
      requiresHumanReview: true
    };
  }

  // Case 3: Sudden deterioration or rapid change
  if (traj.category === "Rapid Change" || (traj.previousScore !== null && traj.currentScore - traj.previousScore >= 18)) {
    return {
      primaryRecommendation: "Flag for prompt human review.",
      priority: "Follow-up Recommended",
      conversationFocus: "Recent acute changes in daily routine, environmental factors, or sudden stressors",
      resources: [
        "Support worker review queue",
        "Optional wellbeing check-in scheduling",
        "Environmental safety & shelter support"
      ],
      rationale: `Rapid upward change of +${traj.rateOfChange * 2} pts detected over recent check-ins.`,
      requiresHumanReview: true
    };
  }

  // Case 4: Increasing stress trajectory
  if (currentCheckIn.stress >= 4 || traj.category === "Gradually Increasing") {
    return {
      primaryRecommendation: "Consider a supportive human check-in.",
      priority: "Follow-up Recommended",
      conversationFocus: "Exploring root causes of persistent stress and daily coping strategies",
      resources: [
        "4-4-4 diaphragmatic breathing guide",
        "Community stress management resources",
        "Optional counselor conversation"
      ],
      rationale: `Self-reported stress is elevated (${currentCheckIn.stress}/5) with an upward trajectory.`,
      requiresHumanReview: true
    };
  }

  // Case 5: Severe sleep disruption
  if (currentCheckIn.sleep <= 2) {
    return {
      primaryRecommendation: "Consider discussing wellbeing and available support resources with a trained worker.",
      priority: "Monitor",
      conversationFocus: "Sleep environment, noise/light conditions, and restorative rest routines",
      resources: [
        "Sleep hygiene & night-time relaxation audio",
        "Comfort and shelter assistance inquiry",
        "Community health worker contact"
      ],
      rationale: `Persistent sleep disruption reported (${currentCheckIn.sleep}/5), which can impact emotional resilience.`,
      requiresHumanReview: false
    };
  }

  // Case 6: Reduced social connection / isolation
  if (currentCheckIn.connection <= 2) {
    return {
      primaryRecommendation: "Consider offering connection and community support resources.",
      priority: "Monitor",
      conversationFocus: "Opportunities for community connection, peer groups, or family liaison",
      resources: [
        "Local community center activities",
        "Peer support gathering information",
        "Family communication assistance"
      ],
      rationale: `Participant self-reported feeling isolated (${currentCheckIn.connection}/5).`,
      requiresHumanReview: false
    };
  }

  // Case 7: Explicit single support request
  if (currentCheckIn.supportRequested) {
    return {
      primaryRecommendation: "Schedule voluntary counselor connection.",
      priority: "Follow-up Recommended",
      conversationFocus: "Participant's self-directed questions or requested topic of support",
      resources: [
        "Assigned support worker outreach",
        "Flexible appointment scheduling"
      ],
      rationale: "Participant selected 'Yes, please have a counselor reach out' in check-in.",
      requiresHumanReview: true
    };
  }

  // Case 8: Recovering after support
  if (traj.category === "Recovering After Support") {
    return {
      primaryRecommendation: "Maintain supportive touchpoints and acknowledge recovery.",
      priority: "Routine",
      conversationFocus: "Reinforcing positive strategies and celebrating steady progress",
      resources: [
        "Personal resilience reflection notes",
        "Ongoing voluntary check-in schedule"
      ],
      rationale: "Indicators have consistently improved following previous human intervention.",
      requiresHumanReview: false
    };
  }

  // Default Case: Low concern / stable
  return {
    primaryRecommendation: "Continue voluntary monitoring.",
    priority: "Routine",
    conversationFocus: "Maintaining healthy daily routines and positive baseline",
    resources: [
      "Daily reflection journal",
      "Self-guided wellbeing library",
      "Emergency resources always accessible"
    ],
    rationale: "Distress indicators remain steady within normal baseline variation.",
    requiresHumanReview: false
  };
};

import { CheckIn, TrajectoryAnalysis, TrajectoryCategory, EarlyWarningForecast } from "../types";
import { calculateRawScore } from "./riskEngine";

/**
 * Dynamic Distress Trajectory & Early-Warning Forecasting Engine
 * 
 * IMPORTANT:
 * This engine generates assistive trajectory categories and heuristic forecast simulations
 * for humanitarian decision-support. It is NOT a clinical prediction model or medical diagnostic system.
 */

export const calculateTrajectory = (
  checkIns: CheckIn[],
  hadInterventionRecently: boolean = false
): TrajectoryAnalysis => {
  if (!checkIns || checkIns.length === 0) {
    return {
      currentScore: 0,
      previousScore: null,
      movingAvg3: 0,
      trend7: [],
      rateOfChange: 0,
      volatility: 0,
      consecutiveWorsening: 0,
      consecutiveImproving: 0,
      recoveringAfterSupport: false,
      suddenChangeDetected: false,
      category: "Stable",
      classification: "Stable",
      categoryRationale: "No check-in history available yet.",
      summary: "No reflections submitted yet. Complete your first check-in to begin.",
      summaryDescription: "No reflections submitted yet. Complete your first check-in to begin."
    };
  }

  // Calculate scores for all historical check-ins in chronological order
  const scores = checkIns.map(c => (c.calculatedScore !== undefined ? c.calculatedScore : calculateRawScore(c)));
  const n = scores.length;
  const currentScore = scores[n - 1];
  const previousScore = n > 1 ? scores[n - 2] : null;

  // Single check-in handling: cannot establish trend or trajectory yet
  if (n === 1) {
    const summaryText = `Initial baseline recorded at ${currentScore}/100. More check-ins are needed before a trend pattern can be identified.`;
    return {
      currentScore,
      previousScore: null,
      movingAvg3: currentScore,
      trend7: [currentScore],
      rateOfChange: 0,
      volatility: 0,
      consecutiveWorsening: 0,
      consecutiveImproving: 0,
      recoveringAfterSupport: false,
      suddenChangeDetected: false,
      category: "Stable",
      classification: "Stable",
      categoryRationale: "Initial baseline recorded. More check-ins are needed before a trend can be identified.",
      summary: summaryText,
      summaryDescription: summaryText
    };
  }

  // 1. Moving average of last 3 check-ins
  const last3 = scores.slice(Math.max(0, n - 3));
  const movingAvg3 = Math.round(last3.reduce((acc, v) => acc + v, 0) / last3.length);

  // 2. 7-check-in trend series
  const trend7 = scores.slice(Math.max(0, n - 7));

  // 3. Rate of change (delta per check-in over recent window)
  let rateOfChange = 0;
  if (last3.length > 1) {
    rateOfChange = Math.round(((last3[last3.length - 1] - last3[0]) / (last3.length - 1)) * 10) / 10;
  }

  // 4. Volatility (Standard Deviation over recent check-ins)
  const mean = movingAvg3;
  const variance = last3.reduce((acc, v) => acc + Math.pow(v - mean, 2), 0) / last3.length;
  const volatility = Math.round(Math.sqrt(variance) * 10) / 10;

  // 5. Consecutive worsening vs improving count
  let consecutiveWorsening = 0;
  let consecutiveImproving = 0;

  for (let i = n - 1; i > 0; i--) {
    const diff = scores[i] - scores[i - 1];
    if (diff > 2) {
      if (consecutiveImproving === 0) consecutiveWorsening++;
      else break;
    } else if (diff < -2) {
      if (consecutiveWorsening === 0) consecutiveImproving++;
      else break;
    } else {
      break;
    }
  }

  // 6. Sudden change detection (e.g. single-step jump >= 20 pts)
  const singleStepDelta = previousScore !== null ? currentScore - previousScore : 0;
  const suddenChangeDetected = Math.abs(singleStepDelta) >= 20;

  // 7. Recovery after support detection
  const recoveringAfterSupport = hadInterventionRecently && consecutiveImproving >= 2 && currentScore < 50;

  // 8. Trajectory Classification
  let category: TrajectoryCategory = "Stable";
  let categoryRationale = "Distress indicators remain within normal baseline variation.";

  if (recoveringAfterSupport) {
    category = "Recovering After Support";
    categoryRationale = "Distress indicators show sustained downward trajectory following human counselor intervention.";
  } else if (suddenChangeDetected && singleStepDelta > 0) {
    category = "Rapid Change";
    categoryRationale = `Acute change of +${singleStepDelta} points detected in the latest check-in.`;
  } else if (consecutiveWorsening >= 2 || (trend7.length >= 3 && rateOfChange >= 4 && currentScore >= 50)) {
    category = "Gradually Increasing";
    categoryRationale = `Consecutive upward movement across recent check-ins (+${rateOfChange} pts/check-in).`;
  } else if (consecutiveImproving >= 2 || (rateOfChange <= -4 && currentScore <= 45)) {
    category = "Improving";
    categoryRationale = "Consistent downward trend in reported distress indicators.";
  } else if (volatility >= 14 && n >= 4) {
    category = "Fluctuating";
    categoryRationale = `High indicator variability (volatility: ${volatility}) across recent check-ins without consistent direction.`;
  } else if (n === 2) {
    const diff = currentScore - (previousScore || 0);
    category = Math.abs(diff) >= 20 ? (diff > 0 ? "Rapid Change" : "Improving") : diff > 5 ? "Gradually Increasing" : diff < -5 ? "Improving" : "Stable";
    categoryRationale = `Early 2-check-in comparison (${diff > 0 ? `+${diff}` : `${diff}`} pts). More check-ins will help identify a clearer pattern.`;
  } else {
    category = "Stable";
    categoryRationale = "Indicators remain stable with steady baseline reflections.";
  }

  const summary = `Current indicator ${currentScore}/100 (3-check-in avg: ${movingAvg3}). Trajectory classified as ${category} (${categoryRationale}).`;

  return {
    currentScore,
    previousScore,
    movingAvg3,
    trend7,
    rateOfChange,
    volatility,
    consecutiveWorsening,
    consecutiveImproving,
    recoveringAfterSupport,
    suddenChangeDetected,
    category,
    classification: category,
    categoryRationale,
    summary,
    summaryDescription: summary
  };
};

/**
 * Predictive Early-Warning Heuristic Forecast
 * 
 * Projects a demonstration confidence range for the next check-in window.
 * Strictly labeled as a demonstration heuristic, NOT a clinical prediction.
 */
export const generateEarlyWarningForecast = (
  checkIns: CheckIn[],
  trajectory: TrajectoryAnalysis
): EarlyWarningForecast => {
  if (!checkIns || checkIns.length === 0) {
    return {
      currentScore: 0,
      projectedMin: 0,
      projectedMax: 0,
      projectedMid: 0,
      trajectory: "Stable",
      signal: "Awaiting first check-in reflection.",
      recommendedAction: "Complete voluntary daily check-in to establish baseline.",
      confidenceBand: "Low",
      historicalSeries: []
    };
  }

  const current = trajectory.currentScore;
  const roc = trajectory.rateOfChange;
  const vol = Math.max(4, trajectory.volatility);

  // Heuristic projection based on rate of change and volatility
  let projectedMid = Math.min(100, Math.max(0, Math.round(current + roc)));

  if (trajectory.category === "Rapid Change") {
    projectedMid = Math.min(100, Math.max(0, Math.round(current + Math.sign(roc || 1) * 8)));
  } else if (trajectory.category === "Recovering After Support") {
    projectedMid = Math.min(100, Math.max(10, Math.round(current - 5)));
  }

  const bandMargin = Math.max(4, Math.round(vol * 0.75 + 3));
  const projectedMin = Math.max(0, projectedMid - bandMargin);
  const projectedMax = Math.min(100, projectedMid + bandMargin);

  let trajDirection: "Increasing" | "Stable" | "Decreasing" | "Fluctuating" = "Stable";
  if (trajectory.category === "Gradually Increasing" || trajectory.category === "Rapid Change") {
    trajDirection = "Increasing";
  } else if (trajectory.category === "Improving" || trajectory.category === "Recovering After Support") {
    trajDirection = "Decreasing";
  } else if (trajectory.category === "Fluctuating") {
    trajDirection = "Fluctuating";
  }

  let signal = "Routine stability expected.";
  let recommendedAction = "Continue voluntary regular reflections.";
  let confidenceBand: "Low" | "Medium" | "High" = "Medium";

  if (checkIns.length === 1) {
    signal = "Single observation recorded. Baseline established.";
    recommendedAction = "Continue daily check-ins to build forecast confidence.";
    confidenceBand = "Low";
  } else if (projectedMid >= 70 || trajectory.currentScore >= 70) {
    signal = "Elevated support need projected based on historical trajectory.";
    recommendedAction = "Consider proactive human check-in or offering counselor contact.";
    confidenceBand = trajectory.trend7.length >= 5 ? "High" : "Medium";
  } else if (projectedMid >= 50 && trajDirection === "Increasing") {
    signal = "Potential increase in support need over next 48-72 hours.";
    recommendedAction = "Schedule follow-up review if next reflection confirms upward trend.";
    confidenceBand = "Medium";
  } else if (trajDirection === "Decreasing") {
    signal = "Positive stabilization trajectory observed.";
    recommendedAction = "Acknowledge progress and maintain optional check-in access.";
    confidenceBand = "High";
  }

  // Build historical + projected series for charting
  const historicalSeries: {
    label: string;
    score: number;
    isProjected?: boolean;
    min?: number;
    max?: number;
  }[] = checkIns.slice(Math.max(0, checkIns.length - 6)).map((c, idx) => ({
    label: `Check-in ${idx + 1}`,
    score: c.calculatedScore !== undefined ? c.calculatedScore : calculateRawScore(c),
    isProjected: false
  }));

  // Append projected next point
  historicalSeries.push({
    label: "Projected Next",
    score: projectedMid,
    isProjected: true,
    min: projectedMin,
    max: projectedMax
  });

  return {
    currentScore: current,
    projectedMin,
    projectedMax,
    projectedMid,
    trajectory: trajDirection,
    signal,
    recommendedAction,
    confidenceBand,
    historicalSeries
  };
};

export const analyzeParticipantTrajectory = (participant: { checkIns: CheckIn[]; notes?: any[] }): TrajectoryAnalysis => {
  const hasIntervention = (participant.notes && participant.notes.length > 0) || false;
  return calculateTrajectory(participant.checkIns || [], hasIntervention);
};

/**
 * AURA Browser Voice Recording & Speech-to-Text Service
 * 
 * Capabilities:
 * 1. Speech-to-Text: Uses Web Speech API (SpeechRecognition / webkitSpeechRecognition)
 *    to generate real client-side transcripts of spoken reflections where supported.
 * 2. Audio Capture: Uses MediaRecorder API to record local audio chunks for playback.
 * 3. NO acoustic emotion inference: Voice tone analysis is explicitly NOT performed.
 */

export interface VoiceRecordingState {
  isSupported: boolean;
  isRecording: boolean;
  durationSeconds: number;
  transcript: string;
  interimTranscript: string;
  audioUrl: string | null;
  error: string | null;
}

export class VoiceRecordingService {
  private mediaRecorder: MediaRecorder | null = null;
  private audioChunks: Blob[] = [];
  private speechRecognition: any | null = null;
  private stream: MediaStream | null = null;
  private timerInterval: any = null;

  public isSpeechRecognitionSupported(): boolean {
    if (typeof window === "undefined") return false;
    return !!(
      (window as any).SpeechRecognition ||
      (window as any).webkitSpeechRecognition
    );
  }

  public isMediaRecorderSupported(): boolean {
    if (typeof window === "undefined" || !navigator.mediaDevices) return false;
    return !!window.MediaRecorder;
  }

  /**
   * Start recording audio and live speech-to-text
   */
  public async startRecording(
    onTranscriptUpdate: (finalText: string, interimText: string) => void,
    onDurationTick: (seconds: number) => void,
    onError: (err: string) => void
  ): Promise<boolean> {
    try {
      this.audioChunks = [];
      let currentDuration = 0;

      // 1. Request microphone access
      if (navigator.mediaDevices && navigator.mediaDevices.getUserMedia) {
        this.stream = await navigator.mediaDevices.getUserMedia({ audio: true });

        if (window.MediaRecorder && this.stream) {
          this.mediaRecorder = new MediaRecorder(this.stream);
          this.mediaRecorder.ondataavailable = (event) => {
            if (event.data.size > 0) {
              this.audioChunks.push(event.data);
            }
          };
          this.mediaRecorder.start(200); // 200ms slices
        }
      }

      // 2. Initialize Web Speech Recognition if available
      const SpeechRecognition =
        (window as any).SpeechRecognition ||
        (window as any).webkitSpeechRecognition;

      let aggregatedTranscript = "";

      if (SpeechRecognition) {
        this.speechRecognition = new SpeechRecognition();
        this.speechRecognition.continuous = true;
        this.speechRecognition.interimResults = true;
        this.speechRecognition.lang = "en-US";

        this.speechRecognition.onresult = (event: any) => {
          let interim = "";
          for (let i = event.resultIndex; i < event.results.length; ++i) {
            if (event.results[i].isFinal) {
              aggregatedTranscript += (aggregatedTranscript ? " " : "") + event.results[i][0].transcript;
            } else {
              interim += event.results[i][0].transcript;
            }
          }
          onTranscriptUpdate(aggregatedTranscript, interim);
        };

        this.speechRecognition.onerror = (e: any) => {
          console.warn("AURA Speech Recognition warning:", e.error);
          if (e.error === "not-allowed") {
            onError("Microphone permission was denied.");
          }
        };

        this.speechRecognition.start();
      }

      // 3. Duration Timer
      this.timerInterval = setInterval(() => {
        currentDuration += 1;
        onDurationTick(currentDuration);
      }, 1000);

      return true;
    } catch (err: any) {
      console.error("Failed to start voice recording:", err);
      onError(err.message || "Microphone access could not be established.");
      this.cleanup();
      return false;
    }
  }

  /**
   * Stop recording and finalize audio Blob URL
   */
  public async stopRecording(): Promise<{ audioUrl: string | null; hasAudio: boolean }> {
    return new Promise((resolve) => {
      if (this.timerInterval) {
        clearInterval(this.timerInterval);
        this.timerInterval = null;
      }

      if (this.speechRecognition) {
        try {
          this.speechRecognition.stop();
        } catch (e) {
          // ignore
        }
      }

      if (this.mediaRecorder && this.mediaRecorder.state !== "inactive") {
        this.mediaRecorder.onstop = () => {
          const audioBlob = new Blob(this.audioChunks, { type: "audio/webm" });
          const audioUrl = URL.createObjectURL(audioBlob);
          this.cleanupStream();
          resolve({ audioUrl, hasAudio: this.audioChunks.length > 0 });
        };
        this.mediaRecorder.stop();
      } else {
        this.cleanupStream();
        resolve({ audioUrl: null, hasAudio: false });
      }
    });
  }

  /**
   * Cleanup tracks and streams
   */
  private cleanupStream() {
    if (this.stream) {
      this.stream.getTracks().forEach((track) => track.stop());
      this.stream = null;
    }
  }

  public cleanup() {
    if (this.timerInterval) {
      clearInterval(this.timerInterval);
      this.timerInterval = null;
    }
    if (this.speechRecognition) {
      try {
        this.speechRecognition.stop();
      } catch (e) {}
      this.speechRecognition = null;
    }
    if (this.mediaRecorder && this.mediaRecorder.state !== "inactive") {
      try {
        this.mediaRecorder.stop();
      } catch (e) {}
    }
    this.cleanupStream();
    this.audioChunks = [];
  }
}

export const voiceRecordingService = new VoiceRecordingService();
